(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["ku"] = {"ui":{"skip":"Derbasî naverokê bibe","back":"← Vegere AI-gile","lang.button":"Ziman: {name}","lang.dialog":"Zimanek hilbijêre","lang.search":"Li zimanan bigere","lang.none":"Tu ziman nehat dîtin","lang.notYet":"{name} hê nehatiye wergerandin","theme.aria":"Rûpelê biguherîne: ronî, tarî an reş","theme.toLight":"Biguherîne rûpela ronî","theme.toDark":"Biguherîne rûpela tarî","theme.toBlack":"Biguherîne rûpela reş (reşa rastîn, ji bo ekranên OLED rehet)","words.underline":"Van peyvan li ser rûpelê bin xet bike","words.underlineHelp":"Mişkê bibe ser peyveke bi xêza xalxalî an lê bitikîne, da ku wateya wê bibînî.","words.col.todo":"Kartên ji bo niha hatine hilbijartin: tîm piştî vê dest bi van dike.","words.col.doing":"AI-yek niha li ser vê kartê dixebite.","words.col.review":"AI-yekê kar qedand; yeke din berî ku bigihîje te kontrol dike.","words.col.verify":"Li benda te ye: biceribîne û bêje gelo dixebite.","words.col.team":"Nîşe an bersivên te, li benda wê ne ku tîm wan hilde.","words.col.done":"Qediya û hate pejirandin.","index.title":"AI-gile: tîma te ya pêşdebirinê ya AI, li ser yek tabloyê","index.description":"AI-gile tabloyeke kanban e ji bo tîmên kodkirinê yên AI. Ew dixebitin dema tu radizê; ji te re yek komek kurt dimîne: tiştên ku divê biryar bidî, biceribînî û qebûl bikî.","hero.logoAlt":"Îkona tabloya AI-gile","hero.h1.html":"Tîma te ya pêşdebirinê ya AI, li ser yek&nbsp;tabloyê.","hero.alpha":"🐣 Pre-alpha ya girtî","hero.alphaTitle":"Zû û nîvco: spas ji bo ceribandinê!","hero.lede":"Ew dest bi çêkirinê dikin dema tu radizê. Tu şiyar dibî û komek kurt dibînî: çend pirs, çend tiştên ji bo ceribandinê, yek an du almasên mor. Bitikîne, qebûl bike, vegere qehwa xwe.","dl.windows":"Sepana Windows","dl.browser":"Di gerokê de bimeşîne","dl.messenger":"📱 Messenger ji bo telefona te","dl.soon":"Zû tê","dl.notify":"🔔 Gava vebû min agahdar bike","dl.notifySmall":"Alpha an beta","hero.secondary":"Agile, lê tîm qet qehweya stand-up naxwaze. (Dîsa jî stand-up çêdikin.)","pitch.h2":"AI-gile bi çiqas peyvan bixwazî","pitch.lede":"Dirêjahiyekê hilbijêre, ji yek peyvê heta 144. Her dirêjahî danasînek taybet e, ji bo wê mezinahiyê hatiye nivîsandin. Sliderê kaş bike an tuşên tîran bikar bîne.","pitch.rangeLabel":"Dirêjahî bi peyvan","pitch.dice":"🎲 guhertoyeke din","pitch.words.one":"{n} peyv","pitch.words.other":"{n} peyv","pitch.letters.one":"{n} tîp","pitch.letters.other":"{n} tîp","pitch.chars.one":"{n} nîşan","pitch.chars.other":"{n} nîşan","count.line.html.one":"{n} kart niha li ser tabloyê ye","count.line.html.other":"{n} kart niha li ser tabloyê ne","people.humans.html.one":"👥 {n} mirov","people.humans.html.other":"👥 {n} mirov","people.agents.html.one":"🤖 {n} ajan","people.agents.html.other":"🤖 {n} ajan","people.working.html.one":"⚡ {n} niha dixebite","people.working.html.other":"⚡ {n} niha dixebitin","pre.title":"AI-gile: li vir tiştek tê avakirin","pre.description":"Li vir tiştek tê avakirin. Tabloyek ku tîmên AI tiştê tu dixwazî ava dikin, û di rê de fêrî te dikin. Niha pre-alpha ya girtî ye bi hevalan re.","pre.h1":"Li vir tiştek tê avakirin. 🤫","pre.line":"Tabloyek ku tîmên AI tiştê tu dixwazî ava dikin, û di rê de fêrî te dikin. Niha pre-alpha ya girtî ye bi hevalan re.","pre.btn":"🔔 Gava vebû min agahdar bike","pre.peek":"Li pişt camê: tabloya rastîn, rasterast. Her kart xêzeke rengîn e.","pre.peekFake":"Li pişt camê: tabloyek di kar de wiha xuya dike.","pre.night":"🌙 Cerdevanê şevê berpirsiyar e · 😴 mirov bêhna xwe vedide","features.aria":"Ew çi dike","f.pile.h":"Yek komek ji bo te","f.pile.html":"<b>Ji bo te</b> her tiştê ku li benda te ye ji hemû projeyan digire: pirs, tiştên ji bo ceribandinê, karên ku tenê mirov dikare bike. Rêza te dibêje çi paşê ye û çiqas dikişîne.","f.sleep.h":"Tîmên ku dema tu radizê dixebitin","f.sleep.p":"Her proje Lead û tîmek ajanên AI heye. Li ser kartekê şirove bike, tîm şiyar dibe, kar dike û bi gavên ku mirovekî westiyayî jî bişopîne vedigerîne.","f.tester.h":"Ceribînerê AI pêşî kontrol dike","f.tester.p":"Berî ku tiştek bigihîje te, ceribîner gavan di kopiyek sepanê de dişopîne û tiştê dîtiye bi dîmenek ekranê nîşan dide. Yên derbasbûyî bi lez bibîne û bi yek tikandinê qebûl bike.","f.proof.h":"Delîl, ne soz","f.proof.p":"Her radestkirin nîşan dide çi guherî: pelan, cudahiyan, dîmenên ekranê. Pêdivî nake ku tu her sepanê vekî da ku bibînî ma qediyaye.","f.chat.h":"Bi Leadên xwe re bipeyive","f.chat.p":"Tabloyeke wekî Discord: ji bo her projeyê yek îkon, ji bo tiştên ku te dixwazin almasên mor. Ji Leadekî re ramanekê binivîse; ew wê dike kart û plan, bi bişkoka ✅ Dest pê bike.","f.tidy.h":"Xwe bi xwe rêkûpêk dike","f.tidy.p":"Kartên girêdayî dibin yek, sernavên tevlihev tên rastkirin, û kontrola token kodê sivik dihêle. Kêmtir tişt ji bo guhertinê, kêmtir tişt ji bo fikirînê.","f.private.h":"Ya te, li ser komputera te","f.private.li1":"Tablo li ser komputera te ya xwe dimeşe û tenê bersiva te dide.","f.private.li2":"Peyamên taybet ên di navbera mirovan de ji dawiyê heta dawiyê şîfrekirî ne.","f.private.li3":"Ne hesab, ne şopîner, ne cookie.","f.lang.h":"Bi zimanê te","f.lang.p":"Zêdetirî 120 ziman, ji Holendî, Weylsî û Japonî heta pirate, Yoda û Klingon, bi vegera bilez bo Îngilîzî ji bo termên pîşeyî.","f.service.h":"Ji ramanekê heta xizmeteke rastîn","f.service.p":"Te bi AI tiştek ava kir ku niha mirov bi kar tînin? Wê wek xizmet nîşan bike û pano alîkariya te dike ku tu wê baş bimeşînî: kontrolên xebitînê, rûpeleke statûyê ya giştî, bûyer bi raporekê, guhertinên ku Here dixwazin, kopiyên ewlehiyê yên ku her roj tên kontrolkirin. Alîkarî her gavê di rê de fêr dike.","msgr.h2":"AI-gile Messenger: tîma te di bêrîka te de","msgr.p1":"Bêyî ku tabloyê vekî bi tîma xwe ya AI re bipeyive. Bi Leadên projeyên xwe û hevalên xwe re biçete, gavên testê yên kartekê bibîne û bersiv bide, hemû ji telefona xwe.","msgr.p2":"Ji bo girêdanê, kodeke QR li ser tabloya xwe skan bike. Cara yekem e? Chateke demo ya dostane dê te bigerîne.","msgr.when":"Pêşî Android, paşê guhertoyeke webê ji bo telefonan û iPhone.","msgr.who":"Leadê projeya te","msgr.b1":"Rastkirina moda tarî amade ye. Tu gavên testê dixwazî?","msgr.b2":"Erê, ji kerema xwe!","msgr.b3":"1. Mîhengan veke. 2. Tarî hilbijêre. Rast xuya dike?","tl.aria":"Rêzkirina demê ji gotûbêja yekem heta nexşerêyê","tl.h2":"Ji gotûbêja yekem heta tiştê ku tê","tl.lede":"Roj û demên rast, di herêma demê ya te de. Piştî îro ew plan e, bê roj sozdayî.","tl.today":"Îro","tl.planned":"plankirî","tl.doing":"di xebatê de","tl.cards.one":"{n} kart","tl.cards.other":"{n} kart","join.h2":"Tevlî bibe","join.lede":"AI-gile ji hêla zilamekî ecêb ê bi rih, bi AuDHD û çend şerên bi tenduristiya derûnî re, û hejmarek mezin ajanên sebirdar ve tê çêkirin. Niha taybet e, di alphayeke girtî de bi hevalan re. Dixwazî gava vebû biceribînî?","join.btn":"Eleqeyê tomar bike","join.small":"Em ê e-name bişînin, tiştek din na","footer.tag":"AI-gile. Bê şopîner, bê cookie, bê qehweya stand-up.","footer.licence":"Lîsansa karsaziyê","footer.status":"Rewş","footer.privacy":"Em çi diparêzin","footer.thanks":"Bang bi saya ChilledChat","form.sending":"Tê şandin…","form.failed":"Nebû: paşê dîsa biceribîne.","form.offline":"Gihîştina AI-gile nebû: paşê dîsa biceribîne.","form.keep":"Em vê tenê ji bo bersivdana te bi kar tînin, paşê jê dibin. Bê şopîner, bê cookie.","form.keepLink":"Em çi diparêzin","interest.title":"AI-gile: gava alpha vebû min agahdar bike","interest.description":"E-name xwe bihêle da ku bibihîzî gava alpha an beta ya girtî ya AI-gile vebe.","interest.h1":"🔔 Gava vebû min agahdar bike","interest.lede":"AI-gile di pre-alphayeke girtî de ye. E-name xwe bihêle û em ê carekê binivîsin, gava ji bo te cih hebe.","interest.email":"E-nameya te","interest.which":"Kîjan ceribandin?","interest.alpha":"Alpha ya girtî: zû, hişk, gelek guhertin","interest.beta":"Beta: aramtir, paşê","interest.both":"Yek ji wan, ya ku pêşî were","interest.submit":"Min têxe lîsteyê","interest.thanks":"Spas! Tu di lîsteyê de yî.","licence.title":"AI-gile: lîsansa karsaziyê","licence.description":"AI-gile di karsaziya xwe de bi kar tînî? Lîsansa karsaziyê ya belaş bixwaze.","licence.h1":"📜 Lîsansa karsaziyê","licence.lede":"AI-gile li ser kar bi kar tînî? Ji me re bêje tu kî yî û tu çi dikî. Heke ew qenciyekê dike, lîsans belaş e.","licence.company":"Şirket","licence.website":"Malper","licence.what":"Tu çi dikî","licence.how":"Çawa alîkariya cîhanê dike","licence.email":"E-name","licence.submit":"Daxwaz bike","licence.thanks":"Spas! Em ê bi e-name bersiv bidin.","status.title":"Rewşa AI-gile","status.h1":"Rewşa AI-gile","status.quiet":"Her tişt aram e","status.intro":"Gelo AI-gile niha dixebite? Ev rûpel her 5 deqîqeyan malper, parvekirina tabloyan, bang û daxistinê kontrol dike.","status.up":"Dixebite (di {ms} ms de bersiv da)","status.slow":"Bersiva kontrola dawî neda, dîsa tê ceribandin","status.down":"Rawestiyaye: bersiva du kontrolên dawî neda","status.svc.web":"Malper","status.svc.web.offers":"Ev malper: AI-gile çi ye, û forma eleqeyê","status.svc.boards":"Parvekirina tabloyan","status.svc.boards.offers":"Tabloyên giştî, peyamên di navbera hevalan de û vexwendin","status.svc.calls":"Bang","status.svc.calls.offers":"Deng, vîdyo û parvekirina ekranê di AI-gile de","status.svc.download":"Daxistin","status.svc.download.offers":"Sazkerê Windowsê û girêdanên vexwendinê","status.checking":"Tê kontrolkirin…","status.offline":"Niha nayê gihîştin xizmeta rewşê (dîsa dixebite)","status.updated":"{ago} nûkirî","status.justNow":"niha","status.min":"{n} xulek berê","status.hours":"{n} saet berê","status.days":"{n} roj berê","privacy.title":"AI-gile: em çi diparêzin","privacy.h1":"Em çi diparêzin","privacy.lede":"Bi kurtî: tenê tiştê tu ji me re dişînî, û ne ji bo demeke dirêj.","privacy.only":"Tenê tiştê tu ji me re dişînî: tiştê tu di formê de dinivîsî, wek e-nameya xwe. Tiştekî din li ser te tune.","privacy.sealed":"Ew tê mohrkirin da ku serverê me nikaribe wê bixwîne: di geroka te de, berî ku derkeve (li ser gerokeke kevntir, gava ku digihîje). Tenê tabloya me ya xwe dikare wê veke.","privacy.server":"Gava ku digihîje tabloya me, ji serverê tê jêbirin. Tiştê ku piştî 30 rojan hê li wir be jî, dîsa tê jêbirin.","privacy.board":"Em wê tenê heta ku me bersiva te da li ser tabloya xwe dihêlin, paşê li wir jî jê dibin.","privacy.none":"Bê şopîner, bê cookie, bê analîtîk.","privacy.local":"Ziman û hilbijartina te ya ronî an tarî di geroka te ya xwe de dimînin. Ew qet ji me re nayên şandin.","privacy.ask":"Dixwazî zûtir were jêbirin? Bersiva e-nameya me bide û ji me re bêje.","live.h2":"Bibîne çawa tê avakirin, rasterast","live.caption":"Her kart veşartî ye: hûn şêweya kar dibînin, ne peyvan.","live.watching.one":"rasterast: {n} dibîne","live.watching.other":"rasterast: {n} dibînin","live.last.now":"Karta dawî nû hat guhastin","live.last.min.one":"Karta dawî {n} deqe berê hat guhastin","live.last.min.other":"Karta dawî {n} deqe berê hat guhastin","live.last.hour.one":"Karta dawî {n} saet berê hat guhastin","live.last.hour.other":"Karta dawî {n} saet berê hat guhastin","live.last.day.one":"Karta dawî {n} roj berê hat guhastin","live.last.day.other":"Karta dawî {n} roj berê hat guhastin","live.offline":"Tabloya rasterast hinekî dimîne. Zû dîsa werin.","live.cols":"Backlog|Ji bo kirinê|Di xebatê de|Tîm kontrol dike|Ji bo te ku test bikî|Ji bo tîmê|Qediya","footer.models":"AI-gile modelên AI ji bo te dixebitîne. Ya ku ew dibêjin û dikin ya wan e, ji ber vê berî ku tu pê bawer bikî kontrol bike.","privacy.ai.h":"Beşa AI","privacy.ai.models":"AI-gile tablo ye. Kar ji aliyê modelên AI yên şirketên din ve tê kirin, wek Claude, Codex û Gemini, bi hesabên te yên xwe.","privacy.ai.check":"Ya ku ew dinivîsin û dikin ji wan tê, û dikare şaş be. Berî ku tu pişta xwe bidî wê an bişînî, kontrol bike.","privacy.ai.files":"Ew di peldankên ku tu girê didî de pelan diguherînin û ferman dimeşînin. Yedek bigire.","privacy.ai.send":"Ya ku tu didî modelekê diçe ba şirketa ku wê dimeşîne, li gorî mercên wan. Mercên her yekê û lêçûnên wê derbas dibin.","privacy.ai.asis":"AI-gile guhertoyeke ceribandinê ya destpêkê ye, wek ku heye tê dayin."},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robot.","Radestkirî."]},{"n":2,"texts":["Kanbana robotan.","Ajanên rêkûpêk.","Raman, çêkirî."]},{"n":3,"texts":["Kanban ji robotan re.","Raman dibin taybetmendî.","Kanbana ajanan, belaş."]},{"n":5,"texts":["Tabloya kanban ku ajan dimeşînin.","Tu kartan dinivîsî. Ajan çêdikin.","Belaş, herêmî, ceribandî, hinekî henekî."]},{"n":8,"texts":["Tabloyeke kanban a belaş ku ajanên AI tê de dixebitin.","Ramanekê binivîse. Ajan çêdikin. Tu qebûl dikî.","Agile ji bo yek mirov û gelek robotên sebirdar."]},{"n":13,"texts":["Tabloyeke kanban li ser komputera te ku ajanên AI kartan hildidin û te serokê wan dihêle.","Ramanekê binivîse. Tîmek ajan wê çêdike. Ceribîner kontrol dike. Tu dibêjî erê.","Bê hesab, bê şopîner: tablo, çend robot û tu, yê ku biryarê dide."]},{"n":21,"texts":["AI-gile tabloyeke kanban e ji bo xebata bi ajanên kodkirinê yên AI re. Ew kartan hildidin; tu wan diceribînî û qebûl dikî.","Her proje Lead û tîmek ajanên AI distîne. Li ser her kartekê şirove bike û tîm dest bi kar dike.","Tabloyeke karên kesane ya belaş li ser komputera te ya xwe dimeşe. Karker robot in. Yê ku dibêje erê tu yî."]},{"n":34,"texts":["Tu ramanan datînî ser tabloyê. Tîmek ajanên AI wan dike taybetmendiyên ku dixebitin, diceribîne, û bi gavên ceribandinê vedigerîne. Tu tişt wekî qediyayî nayê hesibandin heya ku tu nebêjî.","AI-gile tabloyeke kanban a malê ye ku Rich bi alîkariyeke mezin a ajanên ku ew niha îdare dike çêkir. Belaş e, li ser komputera te dimeşe û bi hevalan re tê parvekirin, nayê firotin.","Tabloyeke kanban a asayî bifikire, bi stûnên ji Backlog heta Done, tenê kart ji aliyê ajanên AI ve têne hilgirtin. Pêşketinê radigihînin, gava asê dibin dipirsin, û her dem li benda tiliya te ya bi ber jor dimînin."]},{"n":55,"texts":["AI-gile tabloyeke kanban e ku tîma wê ji ajanên AI pêk tê. Her proje Leadek heye ku kar plan dike û alîkarên ku wê çêdikin. Gava taybetmendiyek amade be, ceribînerê AI wê diceribîne û dîmenek ekranê digire, paşê ew dikeve komeka te. Wê qebûl bike, an şirove bike û ew ê ji nû ve li ser bixebitin.","Ew bi riya yek kesî dest pê kir ku dixwest gelek rûniştinên kodkirinê yên AI di heman demê de bişopîne, û bû tabloyeke rast. Li ser makîna te dimeşe, hesabekî naxwaze û şopîner nîne. Ji bo heval û meraqdaran belaş e. Hê qediyayî nîne, ji ber vê yekê li bendê keviyên hişk û carinan şaşmayîneke biçûk be.","Ev guhertoya dilrast e. Hê jî divê ramanên te hebin, û hê jî divê tu encaman kontrol bikî. Tiştê ku AI-gile dike her tişta di navbera wan de ye: kartan di rêzê de digire, gava tu şirove dikî ajanê rast şiyar dike, tam nîşan dide çi guherî, û hemûyan di yek komeka kurt de ji te re kom dike."]},{"n":89,"texts":["AI-gile tabloyeke kanban a belaş e ku tu li ser komputera xwe dimeşînî. Li şûna mirovan, her proje tîmek ajanên AI heye: Leadek ku ramanên te dike kart û plan, û alîkarên ku kartan li gorî girîngiyê hildidin. Gava tiştek hat çêkirin, ceribînerê AI gavên ceribandinê dişopîne û tiştê dîtiye nîşan dide. Paşê di komekê de bi navê Ji bo te li bendê dimîne. Tu qebûl dikî, an şirove dikî û tîm dîsa hewl dide. Tu kart bêyî te nagihîje Done.","Çend taybetmendiyên ku dibe tu li bendê nebî. Nobedariya şevê stûna Ji bo kirinê dema tu radizê tijî dihêle, kartên ku bersiva te nahewînin hildibijêre. Hejmarkerê token nîşan dide ka ajan îro û vê hefteyê çiqas bikar anîn, û No Token Mode ji wan re dibêje xerc nekin. Tu dikarî ji hevalan re peyam bişînî, û peyamên taybet ji dawiyê heta dawiyê şîfrekirî ne. Tablo bi nêzîkî 120 zimanan dipeyive, di nav de Holendî, Flamî, pirate û Klingon. Tu yek ji wan ne bi pere ye, û kes naxwaze wê bifroşe te.","AI-gile projeyeke biçûk û kesane ye, ne şirket e. Rich dixwest çend projeyên kodkirinê yên AI bişopîne bêyî ku her sepanê veke, ji ber vê yekê wî û ajanan tabloyek ji bo vê çêkirin, paşê bi wê tabloyê ya mayî ya xwe çêkirin. Di pre-alphayeke girtî de ye, ango dixebite, bi piranî, ji bo çend hevalan. Rûpelek bihayan, bultena nûçeyan û plana mezinbûnê tune ne. Heke bikêr xuya dike, dikarî bipirsî ku gava hinekî bêtir vebû biceribînî."]},{"n":144,"texts":["AI-gile tabloyeke kanban e ji bo yek mirov û gelek ajanên AI. Li ser komputera te ya xwe dimeşe û bi tevahî belaş e. Tu proje zêde dikî, û her proje Leadek û tîmeke biçûk distîne. Tu bi Lead re dipeyivî, hinekî wekî Discord, û ramanekê vedibêjî; Lead wê dike kart û plan, paşê li bendê dimîne heta tu Dest pê bike bitikînî. Tîm kartan li gorî girîngiyê dikişîne, bi rêzefermaneyeke hêsan a ji bo modelên zimanî hatî çêkirin. Berî ku tiştek ji te re vegere, ceribînerê AI gavan di kopiyek sepanê de dişopîne û dîmenek ekranê lê zêde dike. Karê qediyayî bi pelên guherî û cudahiyê re dikeve komeka te. Tu qebûl dikî, an şirove dihêlî û tîm şiyar dibe û dîsa hewl dide. Tenê tu dikarî kartekê bibî Done. Hemû ev li ser komputera te ne, bê hesab, bê şopîner, bê cookie.","Rojek bi AI-gile re, bi qasî. Êvarê tu çend şirovan dihêlî: ev bişkojk di cihê şaş de ye, ew lîste divê were rêzkirin, gelo em dikarin moda tarî hebin. Tu diçî razanê. Ajan şirovan dixwînin, guhertinan çêdikin, diceribînin û vedigerînin. Heke stûna Ji bo kirinê vala bibe, nobedariya şevê wê ji backlogê bi kartên ku bersiva te nahewînin tijî dike. Serê sibê yek komek kurt maye: du pirs û çend tiştên ji bo ceribandinê, her yek bi gavên ku mirovekî xewalû jî bişopîne û dîmenek ekranê ku dixebite. Tu bi ser wan de diçî, yên baş qebûl dikî û yên mayî vedigerînî. Hejmarkerê token nîşan dide ku ev hemû çiqas bikar anî, û No Token Mode ji bo hefteyên hişk e. Paşê tu taştê dixwî, ku ajan hê nikarin alîkariya wê bikin.","Pêşî, AI-gile çi nîne. Ne startup e, ne ji bo firotinê ye, û kes daneyên te kom nake. Tabloyeke belaş e ku li ser komputera te dimeşe, bê hesab, bê şopîner û bê cookie. Ew çi ye: yek cihê rêkûpêk ji bo dîtina hemû projeyên kodkirinê yên AI bi carekê, bi tîmek ajanan ku kartan dike û te ku biryaran dide. Kartên girêdayî tevhev dike, sernavên tevlihev rast dike, û çavdêriya sivikbûna kodê dike. Bi nêzîkî 120 zimanan dipeyive, ji Holendî û Flamî heta pirate û Klingon. Heval dikarin ji hev re peyam bişînin, taybet û şîfrekirî. Ji hêla Rich û hejmarek mezin ajanên sebirdar ve hatiye çêkirin, bi piranî bi karanîna xwe. Di pre-alphayeke girtî de ye, ji ber vê yekê li hin deveran hişk e. Heke xweş xuya dike, bi rêzdarî bixwaze û dibe ku zû têkevî."]}],"quips":{"1":"Yek peyv. Zîrek. Dibe ku pir zîrek.","3":"Sê peyv. Ji piraniya rûpelên hilberan jixwe dilrasttir.","8":"Heşt peyv. Hê jî ji stand-upê kurttir.","21":"Dirêjahî, bi awayê, xalên çîrokê ne. Bê guman ew in.","55":"Pêncî û pênc peyv. Du kart qediyan dema te ev dixwend.","144":"Ev ya dirêj e. 233 tune ye. Ajan çûne razanê."}},"timeline":{"first-idea.name":"Ramana yekem","first-idea.line":"Gotûbêja pir pêşîn, berî ku kod hebe.","first-board.name":"Tabloya yekem","first-board.line":"Tabloyek ku çêkirina xwe dişopîne: kart, stûn, kaşkirin û berdan, proje.","team-roles.name":"Tîm û rol","team-roles.line":"Profîlên ajanan, şablonên tîmê, cih û kê çi dike.","install.name":"Sazkirin û weşan","install.line":"Zipek ku heval dikare saz bike, nûkirinên xweber, kanal û vegerandin.","usage-saver.name":"Teserûfa bikaranînê","usage-saver.line":"Bipîve ka meşandin çiqas dike, kodê sivik bihêle, sînorê xwe biparêze.","friends.name":"Heval û parvekirin","friends.line":"DMên taybet, relayeke şîfrekirî, vexwendin, rol û projeyên hevpar.","languages.name":"Ziman","languages.line":"Her nivîsa ekranê di pelê zimanekî de, bi Holendî û Flamî pêşî.","ai-tester.name":"Ceribînerê AI","ai-tester.line":"Ceribînerek her radestkirinê pêşî kontrol dike û tiştê dîtiye nîşan dide.","website.name":"Malper","website.line":"aigile.lol, rûpela teaser û ev rêzkirina demê.","streaming.name":"Chat û streaming","streaming.line":"Discord, Twitch, OBS, moda streamer, GIF û emoji.","no-ai.name":"Guhertoya bê AI","no-ai.line":"Tabloyek ji bo kesên ku bê AI kod dikin, û tabloyên giştî.","night-watch.name":"Nobedariya şevê","night-watch.line":"Nobedar û Scrum Master tîman li ser kar dihêlin dema tu radizê.","p-more.name":"Hemû yên din","p-more.line":"Ramanên biçûktir ku hê li benda rêza xwe ne.","p-android.name":"Telefon û Android","p-android.line":"Bi telefonê bigihîje tabloya xwe, paşê bi sepana Android a xwecihî.","p-release.name":"Alpha û pê ve","p-release.line":"Alpha ya girtî, malpera zindî, paşê beta.","p-languages.name":"Zimanên zêdetir","p-languages.line":"130 ziman, û modeke xwe di zimanî de binghirandinê ji bo hînbûyan.","p-engines.name":"Motorên AI yên zêdetir","p-engines.line":"Ji bo her ajanê Claude, Codex, Gemini, Copilot an Cursor hilbijêre.","p-pro.name":"Pratîka pispor","p-pro.line":"Etîketên rîskê, deriyên merge, kartên bûyerê û asteng-parastinan.","p-self.name":"Xwedîkirina te","p-self.line":"Moda westiyayî, bîranînên xwe-lênihêrînê û 4:20.","p-servers.name":"Server û mezinbûn","p-servers.line":"Mîhengên serverê yên giştî, rol û plankirina mezinbûnê.","p-livestream.name":"Zêdeyên streamingê","p-livestream.line":"Chata Twitch, emojiyên taybet û dîtina zindî ya giştî."},"words":{"button":"📖 Termên pîşeyî","h":"📖 Peyv rave kirî","intro":"Perwerdeya belaş bi zimanekî sade: her peyvê ku tu pê re rû bi rû dibî, ji ramana yekem heta xizmeteke ku mirov pê bawer dikin, bi Agile, çêkirin, ewle hiştin û xebata bi AI re di rê de.","search":"Li peyvekê bigere…","none":"Tu peyv bi vî rengî nîne.","close":"Bigire","count":{"one":"{count} peyv","other":"{count} peyv"},"groups":[{"id":"idea","name":"💡 Raman û vedîtin"},{"id":"plan","name":"🗺️ Plankirina xebatê"},{"id":"agile","name":"🔁 Awayên xebatê yên Agile"},{"id":"build","name":"🛠️ Avakirin"},{"id":"test","name":"🧪 Test û kalîte"},{"id":"change","name":"🔀 Bi ewlehî guhertin"},{"id":"run","name":"🛎️ Xizmetek rêvebirin"},{"id":"sec","name":"🔒 Ewlehî û nepenîtî"},{"id":"ai","name":"🤖 Xebat bi AI re"},{"id":"money","name":"💰 Pere û lîsans"}],"list":[{"id":"discovery","g":"idea","word":"Discovery (vedîtin)","text":"Qonaxa destpêkê ku tê de tê dîtin kîjan pirsgirêk hêjayî çareserkirinê ye û ji bo kê, beriya ku tiştek were çêkirin.","also":["vedîtin","discovery phase","qonaxa vedîtinê"]},{"id":"problemstmt","g":"idea","word":"Daxuyaniya pirsgirêkê","text":"Yek an du hevok ku dibêjin pirsgirêk ji kê re heye, çi ye û çima girîng e, da ku her kes ber bi heman armancê ve here.","also":["daxuyaniyên pirsgirêkê","problem statements"]},{"id":"user","g":"idea","word":"Bikarhêner","text":"Kesê ku tiştê tu çêdikî bi kar tîne. Xebat ji bo hewcedariyên wî ye.","also":["bikarhêneran","users","user"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Stakeholder (aliyê eleqedar)","text":"Her kesê ku xema wî ye xebat çawa bi dawî dibe an ji wê bandor dibe, mîna wan ên ku pereyê wê didin, wê bi kar tînin an piştgiriyê didin.","also":["stakeholders","aliyên eleqedar"]},{"id":"persona","g":"idea","word":"Persona","text":"Kesekî xeyalî lê rastîn ku nûnertiya cureyekî bikarhêneran dike, da ku tîm bikaribe bipirse “gelo ev ji bo Sam hêsan e?”","also":["personas","persona"]},{"id":"userresearch","g":"idea","word":"Lêkolîna bikarhêner","text":"Axaftin û temaşekirina mirovên rast, da ku bizanî ew çi hewce dikin, ne ku texmîn bikî.","also":["hevpeyvînên bikarhêner","user interviews","user research"]},{"id":"journey","g":"idea","word":"Rêwîtiya bikarhêner","text":"Gavên ku kesek diavêje da ku tiştekî bi cih bîne, ji cara yekem ku jê bihîst heta ku diqedîne, li derveyî hilberê te jî. Xêzkirina wê nîşan dide ew li ku asê dibin.","also":["rêwîtiyên bikarhêner","user journeys","customer journey","rêwîtiya xerîdar"]},{"id":"painpoint","g":"idea","word":"Pain point (xala êşê)","text":"Tiştê ku îro mirovan aciz dike an hêdî dike. Hilberên baş xalên êşê ji holê radikin.","also":["pain points","xalên êşê"]},{"id":"assumption","g":"idea","word":"Ferzkirin (assumption)","text":"Tiştê ku tu bawer dikî lê te hê kontrol nekiriye. Nivîsandina ferzkirinan nîşan dide ku divê pêşî çi were testkirin.","also":["ferz","ferzkirin","texmîn","assumptions","assumption"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hîpotez","text":"Texmîna te ya herî baş ku tu dixwazî kontrol bikî, bi tiştê ku tu hêvî dikî çêbibe, mînak “heke meha yekem belaş be, mirov dê qeyd bibin”.","also":["hîpotez","hypotheses","hypothesis"]},{"id":"experiment","g":"idea","word":"Ceribandin","text":"Testeke biçûk a plankirî da ku bizanî raman dixebite yan na, beriya ku tu gelek tiştî li ser wê bidî xeterê.","also":["ceribandin","experiments","experiment"],"noTip":1},{"id":"poc","g":"idea","word":"Proof of concept (PoC)","text":"Hewldaneke zû û xav da ku bibînî gelo raman qet dikare bixebite. Piştî ku bersiv hat, pir caran tê avêtin.","also":["PoC","proof of concept","delîla têgehê"]},{"id":"prototype","g":"idea","word":"Prototîp","text":"Modeleke destpêkê ya hilberê, pir caran wêneyên ku mirov dikare li ser wan bitikîne, da ku raman li ser mirovan bê ceribandin beriya ku bi rêkûpêk were çêkirin.","also":["prototîp","prototypes","prototype"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"Xêzeke hêsan a dîmenekî ku nîşan dide tişt li ku ne, bêyî reng û naveroka rast.","also":["wireframes","wireframe"]},{"id":"mockup","g":"idea","word":"Mockup","text":"Wêneyekî berfireh ê ku dîmen dê çawa xuya bike, bi rengên rast û nivîsê, lê hê tiştek naxebite.","also":["mockups","mock-up","mock-ups","mockup"]},{"id":"bizcase","g":"idea","word":"Business case (sedema karsaziyê)","text":"Sedemên kirina projeyekê: çiqas lê diçe, çi dahat tîne an çi pere teserûf dike, û xetereyên wê.","also":["business cases","sedema karsaziyê"]},{"id":"feasibility","g":"idea","word":"Gengazî","text":"Gelo bi dem, pere û jêhatîbûna ku te heye tiştek bi rastî dikare were çêkirin û lênihêrîna wî bê kirin.","also":["gengaz","feasibility"]},{"id":"outcome","g":"idea","word":"Encam","text":"Guhertina ku tu ji bo mirovan dixwazî, mînak kêmbûna hevdîtinên ji bîr çûyî. Ew ji wê yekê girîngtir e ku tu çiqas tişt çêdikî.","also":["encam","outcomes","outcome"],"noTip":1},{"id":"output","g":"idea","word":"Output (encama xebatê)","text":"Tiştê ku tîm çêdike, mînak dîmeneke nû an raporek. Çêkirina wî bi xwe nayê wê wateyê ku ew alîkariya kesekî dike.","also":["outputs","output","encama xebatê"],"noTip":1},{"id":"successmetric","g":"idea","word":"Pîvana serkeftinê","text":"Hejmarek ku nîşan dide gelo xebatê kir ya ku jê re hatibû kirin, mînak zêdebûna kesên ku siparîşa xwe diqedînin.","also":["pîvanên serkeftinê","success metrics","success metric"]},{"id":"kpi","g":"idea","word":"Nîşandera sereke ya performansê (KPI)","text":"Hejmareke girîng ku tu dişopînî da ku bibînî gelo tişt baş diçin, mînak qeydbûnên her hefteyê.","also":["KPI","KPIs","key performance indicator","nîşandera performansê"]},{"id":"okr","g":"idea","word":"Armanc û encamên sereke (OKR)","text":"Rêbazeke danîna armancan: armanc dibêje tu çi dixwazî, û çend encamên sereke ew hejmar in ku nîşan didin tu gihîştî wir.","also":["OKR","OKRs","Objectives and Key Results"]},{"id":"product","g":"plan","word":"Hilber","text":"Tiştê ku ji bo bikarhênerên xwe tê çêkirin û lênihêrîna wî tê kirin, wekî appek, malperek an amûrek.","also":["hilber","products","product"],"noTip":1},{"id":"vision","g":"plan","word":"Vîzyona hilberê","text":"Daxuyaniyeke kurt a ku dibêje hilber alîkariya kê dike û di demeke dirêj de ber bi ku ve diçe.","also":["daxuyaniya vîzyonê","vision statement","vision"]},{"id":"po","g":"plan","word":"Product owner (PO) (xwediyê hilberê)","text":"Kesê ku biryar dide çi bi kîjan rêzê were çêkirin, da ku tîm her tim li ser tiştê herî girîng bixebite. Di AI-gile de ew tu yî.","also":["PO","product owners","xwediyê hilberê"]},{"id":"pm","g":"plan","word":"Product manager (PM) (rêvebirê hilberê)","text":"Kesê ku li rêya hilberekê dinêre: kîjan pirsgirêkan çareser dike, ji bo kê û çima. PM dikare wateya rêvebirê projeyê jî bide, loma kontrol bike kîjan e.","also":["product managers","rêvebirê hilberê"]},{"id":"projmgr","g":"plan","word":"Rêvebirê projeyê","text":"Kesê ku projeyê di wextê û budçeyê de digire, û dişopîne kî çi dike û heta kengê.","also":["rêvebirên projeyê","project managers","project manager"]},{"id":"roadmap","g":"plan","word":"Roadmap (nexşeya rê)","text":"Planeke giştî ya ku di mehên bê de dê çi were, bi rêz. Arasteyê nîşan dide, ne dîrokên tam, û her ku tu fêr dibî diguhere.","also":["roadmaps","nexşeya rê"]},{"id":"milestone","g":"plan","word":"Milestone (xala girîng)","text":"Xalek di projeyê de ku hêjayî nîşankirinê ye, mînak “guhertoya yekem zindî” an “100 bikarhêner”.","also":["milestones","xala girîng"]},{"id":"mvp","g":"plan","word":"Minimum viable product (MVP) (hilbera herî kêm a bikêrhatî)","text":"Guhertoya herî biçûk a hilberekê ku hê jî ji bo mirovên rast bikêr e, da ku tu zû ji wan fêr bibî.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Pêdivî","text":"Tiştê ku hilbera qediyayî divê bike an be.","also":["pêdivî","requirements","requirement"],"noTip":1},{"id":"scope","g":"plan","word":"Scope (çarçove)","text":"Çi di xebatê de ye û, bi heman girîngiyê, çi tê de nîne.","also":["in scope","out of scope","di çarçoveyê de","li derveyî çarçoveyê"]},{"id":"scopecreep","g":"plan","word":"Scope creep (berfirehbûna bêkontrol)","text":"Gava ku hêdî hêdî tiştên zêdetir li xebatê tên zêdekirin, bêyî ku kes li ser dem an lêçûna zêde li hev bike, loma tu car bi temamî nayê qedandin.","also":["feature creep","berfirehbûna bêkontrol"]},{"id":"feature","g":"plan","word":"Feature (taybetmendî)","text":"Tiştekî ku hilber dikare ji bo mirovan bike, mînak “şîfreya xwe ji nû ve saz bike”.","also":["features","taybetmendî"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"Perçeyeke mezin a xebatê, ji bo carekê pir mezin e, loma di kartên biçûktir de tê parçekirin.","also":["epics","epic"]},{"id":"story","g":"plan","word":"User story (çîroka bikarhêner)","text":"Perçeyeke biçûk a xebatê ku ji aliyê bikarhêner ve hatiye nivîsandin: “Wekî kirrîner, ez dixwazim selika xwe tomar bikim, da ku paşê bi dawî bikim.” Ew sohbeta li ser tiştê were çêkirin dide destpêkirin.","also":["user stories","çîroka bikarhêner"]},{"id":"ac","g":"plan","word":"Acceptance criteria (AC) (pîvanên pejirandinê)","text":"Kontrolên ku kartek divê ji wan derbas bibe da ku wekî qediyayî were hesibandin, beriya destpêkirina xebatê hatine lihevkirin, mînak “piştî ku ez derkevim û dîsa têkevim, selik hê li wir e”.","also":["acceptance criteria","pîvanên pejirandinê"]},{"id":"task","g":"plan","word":"Peywir","text":"Karekî yekane yê ku divê were kirin, pir caran gaveke biçûk a çîrokeke mezintir.","also":["peywir","tasks","task"],"noTip":1},{"id":"ticket","g":"plan","word":"Ticket (bilêt)","text":"Navekî din ê kartê: perçeyek xebatê an daxwazek, ji destpêk heta dawî tê şopandin.","also":["tickets","bilêt"]},{"id":"priority","g":"plan","word":"Pêşînî","text":"Tiştek li gorî hemû tiştên din çiqas girîng an lezgîn e, da ku xebata herî girîng pêşî were kirin.","also":["priorities","pêşînî"],"noTip":1},{"id":"prioritise","g":"plan","word":"Diyarkirina pêşîniyan (prioritisation)","text":"Danîna xebatê bi rêza girîngiyê. Rêbazeke gelemperî MoSCoW e: Divê hebe, Baş e hebe, Dibe ku hebe, Vê carê na.","also":["diyarkirina pêşîniyan","MoSCoW"]},{"id":"estimate","g":"plan","word":"Texmîn","text":"Texmîna te ya herî baş li ser wê yekê ku perçeyek xebatê çiqas mezin e an çiqas dem digire. Texmîn e, ne soz e.","also":["texmînan","estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story points","text":"Rêbazeke texmînkirina mezinahiya xebatê bi berawirdkirina kartan bi hev re (“nêzîkî du caran ji wê mezintir”) li şûna saetan. Ji bo berawirdkirina tîman nînin.","also":["story point","xalên çîrokê"]},{"id":"tshirt","g":"plan","word":"T-shirt sizing","text":"Texmînkirina mezinahiya xebatê wekî S, M, L an XL. Zû ye û ji bo plankirina destpêkê bes e.","also":["t-shirt sizes","mezinahiyên T-shirtê"]},{"id":"poker","g":"plan","word":"Planning poker","text":"Lîstikeke texmînkirinê: her kes di heman demê de karta mezinahiya xwe nîşan dide, paşê yê herî bilind û yê herî nizm şîrove dikin çima.","also":["Scrum poker"]},{"id":"dependency","g":"plan","word":"Girêdayîbûn","text":"Gava ku perçeyek xebatê nikare dest pê bike an biqede heta ku yeke din dest pê neke an neqede.","also":["girêdayîbûn","dependencies","dependency"]},{"id":"blocker","g":"plan","word":"Asteng","text":"Her tiştê ku niha pêşî li pêşveçûna xebatê digire, mînak bersiveke ku nehatiye an amûreke şikestî.","also":["astengan","blockers","blocker"]},{"id":"deadline","g":"plan","word":"Deadline (dema dawî)","text":"Roja ku divê tiştek heta wê were qedandin.","also":["deadlines","dema dawî"],"noTip":1},{"id":"deliverable","g":"plan","word":"Deliverable (hilbera radestkirinê)","text":"Tiştekî konkret ê ku xebat çêdike û radest dike, mînak rûpeleke ku dixebite an raporek.","also":["deliverables","hilbera radestkirinê"]},{"id":"forecast","g":"plan","word":"Pêşbînî","text":"Pêşbîniya tiştê ku îhtîmal e çêbibe, mînak xebat dê kengê biqede, li gorî tiştê ku heta niha tê zanîn.","also":["pêşbînî","forecasts","forecast"],"noTip":1},{"id":"metric","g":"plan","word":"Metric (pîvan)","text":"Her tiştê ku tu bi demê re dipîvî û dişopînî, mînak serdanên rûpelê an çiqas dem ji bo rastkirinekê diçe.","also":["metrics","pîvan"]},{"id":"feedback","g":"plan","word":"Feedback (bersiv)","text":"Tiştê ku mirov li ser xebata te ji te re dibêjin, baş û xirab. Zû û pir caran girtina wê dilê Agile ye.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Lîsteya bendê ya raman û xebatên ku hê nehatine plankirin, yên herî girîng li jor. Tu tişt li wir nayê xebitandin heta ku neçe Ji bo kirinê."},{"id":"sprint","g":"agile","word":"Sprint","text":"Heyameke xebatê ya kurt û sabît (pir caran hefteyek an du, tu carî ne ji mehekê zêdetir) bi armancekê û komeke kartan a lihevkirî ku divê bên qedandin.","also":["sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Kontrola rojane ya bilez: her endamê tîmê çi kir, piştre dê çi bike, û çi rê li ber wî digire. Di Scrumê de jê re daily scrum tê gotin.","also":["standup","stand-ups","daily scrum","daily stand-up","scruma rojane"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Awayekî xebatê ku kart di stûnên tabloyê de diçin (mîna Ji bo kirinê, Di xebatê de, Qediya) û tîm sînor datîne ka di heman demê de çiqas kar di xebatê de be, da ku xebat biherike."},{"id":"wip","g":"agile","word":"WIP limit","text":"WIP kurtkirina work in progress e (xebata di rê de). Sînorê WIP hejmara herî zêde ya kartan e ku stûnek divê di heman demê de bigire, da ku tîm beriya destpêkirina tiştên nû yên heyî biqedîne.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definition of Done","text":"Lîsteya kurt a tîmê ka \"qediya\" çi tê wateyê, wek ceribandî û ravekirî, berî ku kartek bigihîje te. Cêwiya wê, Definition of Ready, dibêje kengî kartek têra xwe zelal e ku dest pê bike.","also":["Definition of Ready","DoD","DoR","pênaseya amadebûnê"]},{"id":"retro","g":"agile","word":"Retro","text":"Nihêrîneke birêkûpêk li paş, li ser ka tîm çawa dixebite, da ku li ser yek an du tiştên ku cara bê baştir bikin li hev bikin. Kurtkirina retrospective. Di AI-gile de retro guhertinekê di awayên xebata tîmê de pêşniyar dike, û tu dibêjî Here an Hê na.","also":["retro","retrospektîf"]},{"id":"swarm","g":"agile","word":"Swarm","text":"Her kes dest dide kar: gelek kes xebatên din datînin aliyekî da ku bi hev re yek tiştê lezgîn rast bikin heta ku were çareserkirin. Di AI-gile de her tîm alîkariya yek projeyê dike, û projeyên din di vê navberê de li bendê dimînin.","also":["swarm","swarming","pez"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Di Scrumê de, kesê ku alîkariya tîmê dike ku baş bixebite: astengan ji holê radike, civînan di rê de digire û adetên baş fêr dike, bêyî ku li kesî serdestiyê bike. Di AI-gile de Lead Scrum Master kartên asê dibîne, tîman hişyar dike û tiştê li benda te ye bi bîra te tîne, li hemû projeyan.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"Awayekî xebatê di gavên biçûk de: hindik çêke, encamên rast pir caran nîşan bide, ji tiştê mirov dibêjin fêr bibe û plan di rê de biguherîne, li şûna ku her tişt pêşî plan bikî.","also":["Agile development","agile ways of working","awayê xebatê yê Agile"]},{"id":"manifesto","g":"agile","word":"Agile Manifesto (Manîfestoya Agile)","text":"Daxuyaniyeke kurt a ku di 2001an de ji aliyê çêkerên nermalavê ve hat nivîsandin. Ew mirovan, encamên ku dixebitin, xebata nêzîk bi xerîdaran re û bersivdana guhertinê dide pêş planên giran û kaxezan.","also":["Manifesto for Agile Software Development","Manîfestoya Agile"]},{"id":"waterfall","g":"agile","word":"Waterfall","text":"Awayê xebatê yê kevntir: her tişt plan bike, paşê her tişt çêke, paşê her tişt test bike, qonaxek li pey qonaxekê. Guhertinên di dawiyê de dijwar û biha ne.","also":["waterfall model","modela waterfall"]},{"id":"iteration","g":"agile","word":"Iteration (dubarekirin)","text":"Gerek ji çêkirin, kontrolkirin û başkirina tiştekî. Xebata Agile zincîreke wan e, û sprint cureyek ji wan e.","also":["iterations","dubarekirin"]},{"id":"increment","g":"agile","word":"Increment (perçeya zêde)","text":"Perçeyeke nû ya ku dixebite û di sprintekê an gerekê de li hilberê tê zêdekirin, û bi tiştê berê hebû re li hev tê.","also":["increments","perçeya zêde"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Awayekî xebatê yê Agile yê navdar: tîmeke biçûk di sprintên kurt de ber bi armancekê ve dixebite, bi rolên diyarkirî û çend civînên birêkûpêk ji bo plankirin, kontrolkirin û başkirinê."},{"id":"scrumteam","g":"agile","word":"Tîma Scrum","text":"Komeke biçûk a ku di Scrumê de xebatê dike: xwediyê hilberê, Scrum Master û pêşdebir.","also":["tîmên Scrum","Scrum teams","Scrum team"]},{"id":"ceremonies","g":"agile","word":"Bûyerên Scrum","text":"Civînên birêkûpêk ên Scrumê: plankirina sprintê, scruma rojane, nirxandina sprintê û retro. Gelek kes ji wan re merasîm (ceremonies) dibêjin.","also":["ceremonies","Scrum ceremonies","merasîmên Scrum"]},{"id":"sprintplan","g":"agile","word":"Plankirina sprintê","text":"Civîna destpêka sprintekê ku tîm tê de li hev dike sprint çima girîng e, kîjan kart werdigire û çawa dest pê dike.","also":["planning meeting","civîna plankirinê","sprint planning"]},{"id":"sprintgoal","g":"agile","word":"Armanca sprintê","text":"Hevokek ku dibêje sprint ji bo çi ye. Karên biçûk dikarin di rê de biguherin, bi şertê ku armanc were bidestxistin.","also":["armancên sprintê","sprint goals","sprint goal"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog","text":"Kartên ji bo sprinta heyî hatine hilbijartin, bi plana tîmê ji bo kirina wan.","also":["sprint backlogs","backloga sprintê"]},{"id":"productbacklog","g":"agile","word":"Product backlog","text":"Lîsteya tije û birêzkirî ya her tiştê ku dibe ji bo hilberê were çêkirin, ya herî girîng li jor. Her ku tu fêr dibî diguhere.","also":["product backlogs","backloga hilberê"]},{"id":"productgoal","g":"agile","word":"Armanca hilberê","text":"Encama mezintir a ku hilber ber bi wê ve dixebite, û alîkariya tîmê dike ku hilbijêre piştre çi bike.","also":["armancên hilberê","product goals","product goal"]},{"id":"refinement","g":"agile","word":"Backlog refinement (paqijkirina backlogê)","text":"Bi rêkûpêk nirxandina backlogê da ku kart werin paqijkirin, parçekirin, birêzkirin û bi hûrgiliyan werin tijîkirin, da ku ji bo hilgirtinê amade bin. Jê re backlog grooming jî tê gotin.","also":["backlog grooming","refinement","paqijkirina backlogê"]},{"id":"sprintreview","g":"agile","word":"Nirxandina sprintê","text":"Civîneke di dawiya sprintekê de ku tîm tê de tiştê qedandiye nîşan dide û dibihîze mirov çi difikirin, da ku biryar bide piştre çi were.","also":["nirxandinên sprintê","sprint reviews","sprint review"]},{"id":"demo","g":"agile","word":"Demo","text":"Nîşandana xebata qediyayî ya ku dixebite, zindî, ji kesên ku xwestibûn re.","also":["demos","demo"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox (çarçoveya demê)","text":"Mîqdareke demê ya sabît ji bo tiştekî. Gava diqede tu radiwestî, tevî ku her tişt nehatibe qedandin.","also":["timeboxed","timeboxes","çarçoveya demê"]},{"id":"velocity","g":"agile","word":"Velocity (leza tîmê)","text":"Tîmek bi gelemperî di sprintekê de çiqas xebat diqedîne, ji bo plankirina ku cara bê çiqas kar bigire tê bikaranîn. Ew ne pûanek e ku nîşan bide mirov çiqas bi zehmet dixebitin.","also":["team velocity","leza tîmê"]},{"id":"capacity","g":"agile","word":"Kapasîte","text":"Piştî betlaneyan û karên din, tîm di heyamekê de çiqas xebatê dikare hilgire.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown chart","text":"Chartek a xebata ku di sprintekê de maye û roj bi roj dadikeve. Heke xet dûz bimîne û danekeve, tiştek asê maye.","also":["burndown","burn-down chart","chartê burndown"]},{"id":"burnup","g":"agile","word":"Burnup chart","text":"Chartek ji xebata qediyayî ya ku bi demê re bilind dibe, li kêleka giştiya plankirî, da ku tu bibînî kengê dê bigihîjî.","also":["burnup","burn-up chart","chartê burnup"]},{"id":"kanbanboard","g":"agile","word":"Tabloya Kanban","text":"Tablo bi xwe: ji bo her qonaxa xebatê stûnek, û kart di nav wan re derbas dibin.","also":["tabloyên Kanban","Kanban boards","Kanban board"]},{"id":"pullsys","g":"agile","word":"Pull system (pergala kişandinê)","text":"Awayekî xebatê ku tê de xebata nû tenê gava dest pê dike ku kesekî cih hebe ji bo wê, li şûna ku li ser kesekî jixwe tije were barkirin.","also":["pull-based","pull system","pergala kişandinê"]},{"id":"flow","g":"agile","word":"Flow (herikîna xebatê)","text":"Xebat çiqas bi hêsanî di nav tabloyê re diçe. Herikîneke baş tê wê wateyê ku kart diçin û li hev kom nabin.","also":["flow of work","herikîna xebatê"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time","text":"Ji dema ku kesek tiştekî dixwaze heta ku diqede çiqas dem diçe.","also":["lead times"]},{"id":"cycletime","g":"agile","word":"Cycle time","text":"Ji dema ku xebat bi rastî li ser kartekê dest pê dike heta ku diqede çiqas dem diçe.","also":["cycle times"]},{"id":"throughput","g":"agile","word":"Throughput","text":"Di hefteyekê de, an di her demeke diyarkirî de, çend kart diqedin.","also":["throughput rate"]},{"id":"bottleneck","g":"agile","word":"Bottleneck (stûyê şûşeyê)","text":"Qonaxa yekane ya ku xebat tê de kom dibe û her tiştê li pey xwe hêdî dike, mîna stûyê teng ê şûşeyekê.","also":["bottlenecks","stûyê şûşeyê"]},{"id":"swimlane","g":"agile","word":"Swimlane","text":"Rêzeke li ser tabloyê ya ku kartên yek cureyî li hev kom dike, mînak xebata lezgîn an kartên tîmekê.","also":["swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"Awayekî xebatê yê ku xebata bêkêr (her tiştê ku alîkariya xerîdar nake) ji holê radike û xebatê di herikînê de dihêle."},{"id":"waste","g":"agile","word":"Waste (xebata bêkêr)","text":"Di Lean de, her tiştê ku hewldan dixwaze lê alîkariya xerîdar nake, mînak li bendê mayîn, dîsa kirina karan an çêkirina tiştên ku kes bi kar nayîne.","noTip":1},{"id":"kaizen","g":"agile","word":"Başkirina berdewam","text":"Her tim hinekî baştir bûn bi guhertinên biçûk ên birêkûpêk, paşê kontrolkirina ka wan alîkarî kir yan na. Retro yek ji van rêyan e. Jê re kaizen jî tê gotin.","also":["kaizen","başkirina berdewam"]},{"id":"selforg","g":"agile","word":"Tîma xwe-rêxistinkirî","text":"Tîmek ku bi xwe biryar dide xebat çawa were kirin, li şûna ku gav bi gav jê re were gotin.","also":["xwe-rêxistinkirin","self-organising","self-managing team","tîma xwe-rêvebir"]},{"id":"crossfunc","g":"agile","word":"Tîma pir-şarezayî","text":"Tîmek ku hemû jêhatîbûnên ku ji bo qedandina xebatê pêwîst in heye, mîna sêwirandin, çêkirin û testkirin.","also":["pir-şarezayî","cross-functional","cross-functional team"]},{"id":"spike","g":"agile","word":"Spike","text":"Lêkolîneke kurt a bi dem ve girêdayî ji bo bersivdana pirsekê beriya ku tu bikevî xebata rast.","also":["spikes","spike"]},{"id":"rework","g":"agile","word":"Rework (dubare kar)","text":"Dubare kirina xebatê ji ber ku cara yekem rast nebû.","also":["reworked","dubare kar"]},{"id":"safe","g":"agile","word":"Scaled Agile (SAFe)","text":"Awayên bikaranîna Agile li ser gelek tîman di rêxistineke mezin de. SAFe (Scaled Agile Framework) mînakeke navdar e.","also":["scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Peldanka kodê ya projeyê bi tevahiya dîroka commitan. Dikare li ser komputerê te, li ser GitHub, an li her duyan be.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Rêzeke xebatê ya cuda di kodê de, da ku bêyî dest dayîna guhertoya sereke guherîn bêne çêkirin.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Wêneyekî tomarkirî yê kodê, bi nîşeyeke kurt a ku çi guherî. Tu her gav dikarî vegerî yekê.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Şandina wêneyên te yên tomarkirî (commit) ji vî komputerî bo kopiya parvekirî ya serhêl, mîna GitHub, da ku yedek bên girtin û kesên din bikaribin wan bistînin."},{"id":"merge","g":"build","word":"Merge","text":"Tevlîkirina guhertinên branchekê nav yeke din, bi gelemperî dîsa nav guhertoya sereke."},{"id":"pr","g":"build","word":"Pull request","text":"Xwestina ku guhertinên branchekê werin kontrolkirin û di guhertoya sereke de werin hevgirtin. Hin malper jê re merge request dibêjin.","also":["PR","PRs","merge request","daxwaza hevgirtinê"]},{"id":"refactor","g":"build","word":"Refactor","text":"Paqijkirina kodê bêyî guhertina ya ku dike: pelên biçûktir, navên zelaltir, dubarekirina kêmtir."},{"id":"bug","g":"build","word":"Bug","text":"Tiştek ku wekî divê naxebite.","also":["bugs"]},{"id":"peerreview","g":"build","word":"Nirxandina hevalan","text":"Cotek çavên din: kesekî ji bilî nivîskar xebatê kontrol dike beriya ku bigihîje te, da ku kêmtir şaşî derbas bibin. Di AI-gile de AIyeke din her kartê kontrol dike.","also":["peer review","code review","nirxandina kodê"]},{"id":"code","g":"build","word":"Kod","text":"Rêwerzên nivîskî yên ku ji komputerê re dibêjin çi bike. Jê re koda çavkaniyê (source code) jî tê gotin.","also":["kod","source code","koda çavkaniyê"],"noTip":1},{"id":"proglang","g":"build","word":"Zimanê bernamesaziyê","text":"Zimanek ji bo nivîsandina kodê, mînak JavaScript, Python an Java. Yên cuda ji bo karên cuda baş in.","also":["zimanên bernamesaziyê","programming languages","programming language"]},{"id":"developer","g":"build","word":"Pêşdebir (dev)","text":"Kesê ku kodê dinivîse û diguherîne. Jê re bernamesaz an endezyarê nermalavê jî tê gotin.","also":["pêşdebir","developer","developers","programmer","programmers","software engineer","bernamesaz"]},{"id":"software","g":"build","word":"Nermalav","text":"Bernameyên ku li ser komputer û têlefonan dixebitin, berevajî makîneyên bi xwe (hardware).","noTip":1},{"id":"app","g":"build","word":"App","text":"Kurtkirina application: bernameyek ku mirov bi kar tînin da ku tiştekî bi cih bînin, li ser têlefonekê, komputerekê an di gerokê webê de.","also":["apps","application","applications","sepan"],"noTip":1},{"id":"webapp","g":"build","word":"Web app","text":"Appek ku di gerokê webê de dixebite, loma tiştek nayê sazkirin.","also":["web apps","web application"]},{"id":"frontend","g":"build","word":"Front end","text":"Beşa appê ya ku tu dibînî û li ser dibitikînî: dîmen, bişkok û peyv, pir caran di gerokê te de.","also":["front-end","frontend"]},{"id":"backend","g":"build","word":"Back end","text":"Beşa li paş perdeyê ya appê ya ku daneyan digire û gava tu li tiştekî dibitikînî kar dike, mînak kontrolkirina şîfreya te.","also":["back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Xebata li ser front end û back end herduyan.","also":["full-stack"]},{"id":"ui","g":"build","word":"Navrûya bikarhêner (UI)","text":"Tiştê ku mirov li ser dîmenê dibîne û bi kar tîne: sêwirana rûpelê, bişkok, menû û nivîs.","also":["UI","user interface","navrû"]},{"id":"ux","g":"build","word":"Ezmûna bikarhêner (UX)","text":"Bikaranîna tiştekî çawa tê hîskirin: hêsan, zelal û xweş, an tevlihev û hêdî.","also":["UX","user experience","ezmûna bikaranînê"]},{"id":"accessibility","g":"build","word":"Gihîştbarî (a11y)","text":"Çêkirina tiştan ku her kes bikaribe bi kar bîne, tevî kesên ku baş nabînin, nikarin mişk bi kar bînin an xwînerê dîmenê bi kar tînin.","also":["a11y","gihîştbarî","accessibility"]},{"id":"responsive","g":"build","word":"Sêwirana responsive","text":"Çêkirina rûpelan da ku li her mezinahiya dîmenê, ji têlefonekê heta monîtorekî mezin, bi cih bibin û baş bixebitin.","also":["sêwirana bersivdar"]},{"id":"designsys","g":"build","word":"Design system (pergala sêwiranê)","text":"Kîteke hevpar a reng, nivîsk, bişkok û rêzikan, da ku her dîmen heman awayî xuya bike û tevbigere.","also":["design systems","pergala sêwiranê"]},{"id":"architecture","g":"build","word":"Mîmarî (architecture)","text":"Şeklê giştî yê pergalekê: beşên sereke çi ne û çawa bi hev re diaxivin."},{"id":"database","g":"build","word":"Database (DB) (bingeha daneyan)","text":"Embareke birêkûpêk a agahiyan, mîna tabeleyeke hesabê (spreadsheet) ya pir bi hêz ku app dikare bixwîne û biguherîne.","also":["database","databases","DB","bingeha daneyan"]},{"id":"schema","g":"build","word":"Database schema (şemaya databaseê)","text":"Plana databaseyekê: kîjan tabloyên agahiyan hene û di her yekê de çi cih digire.","also":["schema","şema"]},{"id":"sql","g":"build","word":"SQL","text":"Kurtkirina structured query language: zimanê ku ji bo pirsîna agahiyan ji gelek databaseyan, an guhertina wan, tê bikaranîn.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Dane","text":"Agahiyên ku komputer digire, mînak nav, siparîş an mîheng.","also":["dane","dataset","datasets","data"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"Komputerek ku her dem vêketî ye û bersiva daxwazên komputerên din dide, mînak şandina rûpeleke webê gava tu diçî serdanê.","also":["servers","server","pêşkêşker"]},{"id":"client","g":"build","word":"Client","text":"Aliyê ku tiştekî dixwaze, bi gelemperî gerok an appa te, ku bi serverekî re diaxive. Di karsaziyê de wateya wê xerîdar jî ye.","also":["clients","xerîdar"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Kurtkirina application programming interface: lîsteyeke daxwazên diyarkirî ku bernameyek dikare ji ya din bike, mînak pirsîna pêşbîniya hewaya îro ji xizmeteke hewayê.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"Yek tişt ji lîsteya APIyê: navnîşana webê ya ku bername dikare bang bike da ku tiştekî bistîne an bişîne.","also":["endpoints","endpoint"]},{"id":"integration","g":"build","word":"Entegrasyon (integration)","text":"Girêdana du pergalan da ku bi hev re bixebitin, mînak dikana te siparîşan ji nermalava te ya hesaban re dişîne.","also":["integrations","entegrasyon","integration"]},{"id":"webhook","g":"build","word":"Webhook","text":"Peyamek ku pergalek bi xwe di cih de ji ya din re dişîne gava tiştek çêdibe, mînak “pere hat”.","also":["webhooks","webhook"]},{"id":"library","g":"build","word":"Library (pirtûkxane)","text":"Koda amade ya ku kesekî din nivîsiye û tu dikarî dîsa bi kar bînî li şûna ku bi xwe binivîsî.","also":["libraries","pirtûkxane"],"noTip":1},{"id":"framework","g":"build","word":"Framework (çarçove)","text":"Avahiyeke amade ji bo çêkirina appekê ku pir ji wê diyar dike ka kod çawa tê rêzkirin, mîna çarçoveya malekê ku tu tijî dikî.","also":["frameworks","çarçove"]},{"id":"sdk","g":"build","word":"Software development kit (SDK)","text":"Qutiyek amûr, kod û mînakan ji bo çêkirina nermalavê ji bo yek platformê an xizmetê.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Girêdayîbûna nermalavê","text":"Pirtûkxane an amûreke ku koda te ji bo xebatê hewce dike. Nûkirina wan ji bo ewlehiyê girîng e.","also":["software dependencies","software dependency","girêdayîbûnên nermalavê"]},{"id":"package","g":"build","word":"Package (pakêt)","text":"Komeke koda amade ku tu dikarî saz bikî û di projeyekê de bi kar bînî.","also":["packages","pakêt"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Package manager (rêvebirê pakêtan)","text":"Amûrek ku pakêtên ku koda te pê ve girêdayî ye tîne û nû dike. npm yek ji yên herî naskirî ye.","also":["package managers","npm","rêvebirê pakêtan"]},{"id":"git","g":"build","word":"Git","text":"Amûra ku herî zêde tê bikaranîn ji bo girtina dîroka guhertinên kodê, wekî commit û branch."},{"id":"github","g":"build","word":"GitHub","text":"Malperek ku repoyên Git bi serhêl digire, da ku tîm kodê parve bikin, guhertinan binirxînin û xebatê bişopînin."},{"id":"vcs","g":"build","word":"Version control (kontrola guhertoyan)","text":"Girtina dîrokeke tijî ya her guhertina pelan, da ku tu bibînî kê çi guhert û heke hewce be vegerî. Git vê dike.","also":["source control","version control system","kontrola guhertoyan"]},{"id":"clone","g":"build","word":"Clone","text":"Çêkirina kopiya xwe ya tijî ya repoyekê, bi dîroka wê, li ser komputerê te.","also":["cloned","cloning","clone"]},{"id":"pull","g":"build","word":"Pull","text":"Anîna commitên herî dawî ji kopiya parvekirî (mîna GitHub) bo komputerê te. Berevajiyê push e.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Branchê sereke","text":"Guhertoya fermî ya kodê ku her kes li ser bingeha wê dixebite, pir caran jê re main an master tê gotin.","also":["master branch","main branch","branchê sereke"]},{"id":"conflict","g":"build","word":"Merge conflict (nakokiya hevgirtinê)","text":"Gava du guhertin bi awayên cuda dest didin heman rêzan, loma komputer nikare wan bigihîne hev û divê mirovek hilbijêre.","also":["merge conflicts","merge conflict","nakokiya hevgirtinê"]},{"id":"diff","g":"build","word":"Diff","text":"Dîmenek ku bi rastî nîşan dide di navbera du guhertoyan de çi guherî: rêzên zêdekirî û rêzên hatine rakirin.","also":["diffs","diff"]},{"id":"fork","g":"build","word":"Fork","text":"Kopiya te ya taybet a repoya kesekî din, ku tu dikarî biguherînî bêyî ku bandorê li ya wî bike.","also":["forks","forked","fork"]},{"id":"script","g":"build","word":"Script","text":"Bernameyeke kurt a ku bi tena serê xwe karekî dike, mînak rêzkirina pelan an destpêkirina appê.","also":["scripts","script"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"Veguherandina kodê bo tiştekî ku amade ye bixebite, an encama amade bi xwe.","also":["builds","build"],"noTip":1},{"id":"compile","g":"build","word":"Compile","text":"Wergerandina koda ku mirovan nivîsiye bo awayekî ku komputer rasterast dikare bimeşîne.","also":["compiler","compile"]},{"id":"cli","g":"build","word":"Rêzika fermanan (CLI)","text":"Paceyeke nivîsê ya ku tu tê de rêwerzan ji bo komputerê dinivîsî li şûna ku bitikînî. Jê re terminal jî tê gotin.","also":["command line","command-line","CLI","terminal","rêzika fermanan"]},{"id":"config","g":"build","word":"Mîheng (config)","text":"Mîhengên ku kontrol dikin nermalav çawa tevdigere, ji kodê cuda têne girtin da ku guhertin hêsan be.","also":["config","configuration","mîheng"],"noTip":1},{"id":"envvar","g":"build","word":"Environment variable (guhêrka jîngehê)","text":"Mîhenga ku dema destpêkirinê bi bernameyekê re tê dayîn, pir caran ji bo navnîşan an şîfreyan tê bikaranîn da ku di kodê de neyên nivîsandin.","also":["environment variables","env var","guhêrka jîngehê"]},{"id":"debugging","g":"build","word":"Debugging","text":"Lêgerîna ka çima tiştek naxebite, û rastkirina wî.","also":["debug","debugged","debugging"]},{"id":"pairing","g":"build","word":"Pair programming (bernamesaziya cotî)","text":"Du kes (an kesek û AIyek) bi hev re li ser heman kodê dixebitin, yek dinivîse û yek kontrol dike.","also":["pairing","bernamesaziya cotî"]},{"id":"docs","g":"build","word":"Belgekirin (docs)","text":"Şîroveyên nivîskî li ser ka tiştek çawa dixebite an çawa tê bikaranîn.","also":["documentation","docs","belgekirin"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"Pela yekem a ku di repoyekê de tê xwendin: proje çi ye û çawa tê xebitandin.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Pergala kevn (legacy)","text":"Pergaleke kevn a ku hê tê bikaranîn û guhertina wê zehmet e, pir caran ji ber ku kêm kes hê jê fam dikin.","also":["legacy systems","legacy code","legacy","pergala kevn"]},{"id":"techdebt","g":"build","word":"Deynê teknîkî (technical debt)","text":"Kurtebirên ku niha dem diparêzin lê guhertinên paşê hêdî dikin, mîna deynekî ku faîz li ser kom dibe. Refactoring wî deynî kêm dike.","also":["tech debt","technical debt","deynê teknîkî"]},{"id":"test","g":"test","word":"Test","text":"Kontrolkirina ku tiştek wekî divê dixebite. Hin testan komputer her carê ku kod diguhere bi xwe dimeşîne; yên din ew in ku tu kartekê qediyayî diceribînî beriya ku wê bipejirînî.","also":["tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Kurtkirina quality assurance: her tiştê ku tê kirin da ku xebat beriya zindîbûnê rast be. Di AI-gile de ev kontrolên otomatîk in: gava QA sor be, tiştek têk çûye, û heta ku neyê rastkirin nikare zindî bibe.","also":["kontrola kalîteyê","misogerkirina kalîteyê"]},{"id":"testpile","g":"test","word":"Stûna ceribandinê","text":"Kartên qedandî yên ku li benda ceribandina te ne, yek li pey yekê. Yekê qebûl bike an bi notekê paşde bişîne, û ya din tê.","also":["stûna ceribandinan","test pile"]},{"id":"autotest","g":"test","word":"Testa otomatîk","text":"Kontroleke ku komputer her carê ku kod diguhere bi xwe dimeşîne, da ku şaşî zû werin girtin.","also":["automated tests","automatic tests","automated test","testên otomatîk"]},{"id":"manualtest","g":"test","word":"Testa destan","text":"Kesek xebatê bi destan diceribîne da ku bibîne gelo wekî ku divê tevdigere yan na.","also":["manual tests","manual testing","manual test","testên destan"]},{"id":"unittest","g":"test","word":"Unit test","text":"Kontroleke otomatîk a biçûk a perçeyekî pir biçûk ê kodê bi tena serê wî.","also":["unit tests","unit test"]},{"id":"integtest","g":"test","word":"Integration test","text":"Kontroleke ku gelek beş bi hev re rast dixebitin, ne tenê yek bi yek.","also":["integration tests","integration test"]},{"id":"endtoend","g":"test","word":"End-to-end test (E2E)","text":"Testeke ku wekî bikarhênerekî rast ji destpêk heta dawî tevdigere, mînak qeydbûn, kirîn û dayîna pereyan.","also":["E2E","end-to-end tests"]},{"id":"uat","g":"test","word":"User acceptance testing (UAT)","text":"Kesên ku xebat xwestine bi xwe wê diceribînin û dibêjin gelo ew tiştê ku hewce dikin dike yan na. Komeya testê ya AI-gile guhertoya AI-gile ya vê yekê ye.","also":["UAT","acceptance testing"]},{"id":"regression","g":"test","word":"Regression","text":"Tiştekî ku berê dixebitî lê piştî guhertinekê şikest. Testên regressionê kontrol dikin ku tiştên kevn hê dixebitin.","also":["regressions","regression test","regression tests","regression testing","regression"]},{"id":"smoke","g":"test","word":"Smoke test","text":"Kontroleke pir zû ka tiştên sereke bi giştî dixebitin, mînak tam piştî ku guhertinek zindî dibe. Heke têk biçe, raweste û binêre.","also":["smoke tests","smoke test"]},{"id":"exploratory","g":"test","word":"Testa vekolînê","text":"Ceribandina serbest a hilberê bi gelek awayên cuda, da ku pirsgirêkên ku kontrolên plankirî nabînin werin dîtin.","also":["exploratory test","exploratory tests","exploratory testing","testa vekolînê"]},{"id":"testcase","g":"test","word":"Test case","text":"Yek senaryoya nivîskî ku were ceribandin: gav, û tiştê ku divê çêbibe.","also":["test cases","test case"]},{"id":"coverage","g":"test","word":"Test coverage (nixumandina testê)","text":"Çiqas ji kodê bi testên otomatîk tê kontrolkirin. Zêdetir bi gelemperî ewletir e, lê nixumandineke bilind bi tenê nîşan nade ku baş dixebite.","also":["code coverage","nixumandina testê"]},{"id":"testdata","g":"test","word":"Daneyên testê","text":"Agahiyên mînak ên çêkirî yên ku di dema testkirinê de tên bikaranîn, da ku hûrgiliyên taybet ên kesekî rast neyên eşkerekirin.","also":["test fixtures","test data","daneyên testê"]},{"id":"edgecase","g":"test","word":"Edge case (rewşa sînorê)","text":"Rewşeke neasayî li sînoran, mînak formeke vala an navekî bi apostrofê, ku tişt pir caran lê dişkin.","also":["edge cases","rewşa sînorê"]},{"id":"happypath","g":"test","word":"Happy path (rêya bextewar)","text":"Rêya asayî ya ku her tişt rast diçe. Testeke baş rêyên ne bextewar jî diceribîne."},{"id":"perftest","g":"test","word":"Testa performansê","text":"Kontrolkirina ku tiştek çiqas bilez e û di bin zextê de çiqas baş li xwe digire.","also":["performance test","performance tests","performance testing","testa performansê"]},{"id":"loadtest","g":"test","word":"Load testing","text":"Kontrolkirina ku pergalek gava gelek kes di heman demê de bi kar tînin çawa li xwe digire.","also":["load test","load tests","load testing"]},{"id":"sectest","g":"test","word":"Testa ewlehiyê","text":"Lêgerîna qelsiyên ku dikarin rê bidin kesek pergalê xirab bi kar bîne an tiştên ku divê nebîne bibîne.","also":["security test","security tests","security testing","testa ewlehiyê"]},{"id":"accesstest","g":"test","word":"Testa gihîştbariyê","text":"Kontrolkirina ku mirovên bi şiyanên cuda dikarin hilberê bi kar bînin, tevî bi xwînerê dîmenê an tenê bi klavyeyê.","also":["accessibility test","accessibility testing","testa gihîştbariyê"]},{"id":"linting","g":"test","word":"Linting","text":"Kontroleke otomatîk a ku şaşiyên îhtîmalî û şêwazê tevlihev di kodê de dibîne, mîna kontrolkera rastnivîsê ji bo bernameyan.","also":["linter","lint","linting"]},{"id":"static","g":"test","word":"Static analysis (analîza statîk)","text":"Kontrolkirina kodê ji bo pirsgirêkan bi xwendina wê ya otomatîk, bêyî ku were meşandin.","also":["static code analysis","analîza statîk"]},{"id":"flaky","g":"test","word":"Flaky test (testa nearam)","text":"Testeke ku carinan derbas dibe û carinan têk diçe bêyî sedemeke zelal, loma mirov nikare bi temamî pê bawer bike.","also":["flaky tests","testa nearam"]},{"id":"repro","g":"test","word":"Dubarekirina bugê (repro)","text":"Bi zanebûn dîsa çêkirina bugekê bi şopandina heman gavan, da ku were lêkolîn û rastkirin. Nivîsandina wan gavan beşa herî bikêr a raporeke bugê ye.","also":["repro","reproduce","steps to reproduce","gavên dubarekirinê"]},{"id":"severity","g":"test","word":"Giraniya pirsgirêkê","text":"Bandora pirsgirêkekê çiqas xirab e, ji aciziyeke biçûk heta ku her tişt radiweste.","also":["severity level","severity","asta giraniyê"]},{"id":"deploy","g":"change","word":"Deploy","text":"Kopîkirina guhertoyeke nû ya nermalavê bo komputerên ku wê dimeşînin, mîna kopiyeke testê an xizmeta zindî."},{"id":"release","g":"change","word":"Berdan","text":"Pakêteke bi nav a karê qedandî ku bi hev re zindî diçe, bi notên kurt ka çi guherî. 🚀 Berdan notan ji kartên qedandî dinivîse.","also":["berdan","release"]},{"id":"rollback","g":"change","word":"Vegerandin","text":"Vegera guhertoya dawî ya ku dixebitî gava ya nû pirsgirêk çêdike. Di AI-gile de, Roll back gavên betalkirinê yên li ser her guhertinê hatine nivîsandin di yek lîsteya kontrolê de kom dike.","also":["rollback","vegere","hat vegerandin"]},{"id":"live","g":"change","word":"Zindî","text":"Guhertoya rastîn a ku mirov bi kar tînin, ne kopiyeke ji bo ceribandinê. Pêşdebir jê re production jî dibêjin.","also":["production","hilberîn"],"noTip":1},{"id":"change","g":"change","word":"Guhertin","text":"Guhertineke plankirî li tiştekî ku mirov pê bawer dikin, pêşî tê nivîsandin: çi, çima, risk, kengî û çawa were betalkirin. Bi 🔀 Guhertinekê bixwaze dest pê bike.","also":["guhertin","daxwaza guhertinê"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Tiştek ku dikare xelet biçe, li gor ka çiqas îhtîmal e û çiqas xirab dibe tê pûankirin. ⚠️ Risk wan di yek lîsteyê de digire, pûana herî bilind pêşî, her yek bi dîrokeke ji bo dîsa nihêrînê.","also":["risk","tomara riskan"]},{"id":"chgwin","g":"change","word":"Pencereya guhertinê","text":"Demên ku guhertin dikarin zindî biçin, mînak êvareke Sêşemê ya aram. Li derveyî pencereyê karta guhertinê nayê qedandin, heke ne rewşeke acîl be.","also":["pencereyên guhertinê","change window"]},{"id":"gonogo","g":"change","word":"Here / Neçe","text":"Kontrola dawî tam beriya ku guhertinek zindî bibe: her kesê ku divê erê bike dibêje Here an Neçe. Tenê gava her kes bibêje Here berdewam dike.","also":["go/no go","go-no-go","here/neçe"]},{"id":"approval","g":"change","word":"Erêkirin","text":"Li benda \"erê\" mayîn berî ku kar dest pê bike. Kartek ku hevalek vedike, an guhertinek, di ✅ Erêkirin de li bendê dimîne heta ku tu wê erê bikî an red bikî.","also":["erêkirin","pejirandin"]},{"id":"quiettime","g":"change","word":"Dema bêdeng","text":"Heyameke demê, mîna dema weşana zindî, demoyekê an şevê, ku tê de tu tişt zindî nabe. Tîm xebat û testkirinê berdewam dikin, lê zindîbûn li bendê dimîne heta ku biqede. Li cihên din jê re change freeze tê gotin.","also":["demên bêdeng","change freeze","cemidandina guhertinan"]},{"id":"devops","g":"change","word":"DevOps","text":"Awayekî xebatê ku kesên nermalavê çêdikin û kesên wê dimeşînin wekî yek tîm dixebitin, bi gelek otomasyonê, da ku guhertin pir caran û bi ewlehî zindî bibin."},{"id":"cicd","g":"change","word":"CI/CD (entegrasyon û radestkirina berdewam)","text":"Guhertinên her kesî pir caran bi guhertoya sereke ve tên girêdan û her carê bi otomatîk tên kontrolkirin (entegrasyona berdewam), da ku nermalav her dem bi tikandina bişkokekê ji bo zindîbûnê amade be (radestkirina berdewam).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Deploymenta berdewam","text":"Gaveke din ji radestkirina berdewam: her guhertina ku kontrolan derbas dike bi xwe zindî dibe, bêyî bişkokekê.","also":["continuous deployments","continuous deployment","deploymenta berdewam"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"Rêzeya gavên otomatîk ên ku guhertinek di rêya xwe ya ber bi zindî ve derbas dike, mîna build, test, paşê deploy.","also":["pipelines","pipeline"]},{"id":"environment","g":"change","word":"Jîngeh (environment)","text":"Kopiyeke cuda ya pergalê ji bo armancekê, mînak yek ji bo çêkirinê, yek ji bo testkirinê û ya zindî.","also":["environments","environment","jîngeh"],"noTip":1},{"id":"devenv","g":"change","word":"Jîngeha pêşvebirinê","text":"Kopiya ku pêşdebirek tê de dixebite, pir caran li ser komputerê xwe, ku şikandina tiştan zirarê nade kesî.","also":["dev environment","development environment","jîngeha dev"]},{"id":"testenv","g":"change","word":"Jîngeha testê","text":"Kopiyeke cuda ya pergalê ku tenê ji bo testkirinê tê bikaranîn, da ku xizmeta rast neyê destlêdan.","also":["test environments","test environment","jîngehên testê"]},{"id":"staging","g":"change","word":"Staging","text":"Kopiyeke dawî ku tam mîna ya zindî hatiye sazkirin, ji bo kontrola dawî beriya ku guhertinek zindî bibe.","also":["staging environment","staging"]},{"id":"artifact","g":"change","word":"Build artifact","text":"Pel an girêka ku build çêdike, amade ye ku were hilanîn, kontrolkirin an zindîkirin.","also":["build artifacts","artifact"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"Rastkirineke lezgîn ku zû zindî tê kirin, li derveyî plana asayî, ji ber ku tiştekî girîng şikestiye.","also":["hotfixes","hotfix"]},{"id":"patch","g":"change","word":"Patch","text":"Nûkirineke biçûk a ku bugekê rast dike an kuneke ewlehiyê digire. Zû danîna patchên ewlehiyê girîng e.","also":["patches","security patch","security patches","patch","patchên ewlehiyê"]},{"id":"version","g":"change","word":"Hejmara guhertoyê","text":"Nîşanek mîna 2.4.1 ku dibêje kîjan weşan li cem te ye. Pir caran hejmara yekem ji bo guhertinên mezin û ya dawî ji bo rastkirinên biçûk diguhere.","also":["version numbers","semantic versioning","hejmarên guhertoyê"]},{"id":"relnotes","g":"change","word":"Release notes (têbiniyên weşanê)","text":"Lîsteyeke kurt û sade ya ku di weşanekê de çi guherî, ji bo kesên wê bi kar tînin, tevî rastkirin û sînorên naskirî. Jê re changelog jî tê gotin.","also":["changelog","change log","release notes","têbiniyên weşanê"]},{"id":"flag","g":"change","word":"Feature flag","text":"Guhêrokeke vekirin û girtinê ji bo taybetmendiyekê, da ku xebata nû veşartî zindî bibe û bêyî weşaneke nû were vekirin (an dîsa girtin).","also":["feature flags","feature toggle","feature toggles","feature flag"]},{"id":"rollfwd","g":"change","word":"Roll forward","text":"Rastkirina weşaneke xirab bi derxistina zû ya guhertoyeke nû ya rastkirî, li şûna vegerê bo ya kevn.","also":["rolling forward","rolled forward","roll forward"]},{"id":"canary","g":"change","word":"Canary release","text":"Guhertinek pêşî ji bo komeke biçûk zindî kirin, û ji bo her kesî tenê gava baş xuya bike. Navê wê ji qenaryayên ku karkerên kanê wekî hişyarkirina zû dibirin binê erdê tê.","also":["canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Blue-green deployment","text":"Girtina du kopiyên pergala zindî û veguhastina mirovan bi carekê ve bo ya nû, da ku heke xirab biçe tu yekser vegerî ya berê.","also":["blue-green","blue green deployment"]},{"id":"zerodown","g":"change","word":"Zero-downtime deployment","text":"Zindîkirina guhertoyeke nû bêyî ku xizmet ji bo bikarhêneran tu carî raweste.","also":["zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"Change enablement (rêvebirina guhertinê)","text":"Alîkarîkirin ku guhertin biserkevin: nirxandina xeteriyê, wergirtina erêkirina rast û hilbijartina demeke baş. Jê re change management jî tê gotin.","also":["change management","rêvebirina guhertinê"]},{"id":"cab","g":"change","word":"Change advisory board (CAB)","text":"Komek ku guhertinên girîng dinirxîne û li hev dike gelo û kengê dikarin pêk werin.","also":["CAB"]},{"id":"stdchange","g":"change","word":"Guhertina standard","text":"Guhertineke bi xeterî kêm ku her carê bi heman awayê ceribandî tê kirin, loma ji berê ve tê erêkirin.","also":["standard changes","standard change","guhertinên standard"]},{"id":"normchange","g":"change","word":"Guhertina asayî","text":"Guhertineke ku beriya berdewamkirinê divê were kontrolkirin û erêkirin.","also":["normal changes","normal change","guhertinên asayî"]},{"id":"emergchange","g":"change","word":"Guhertina acîl","text":"Guhertineke ku divê tavilê çêbibe da ku pirsgirêkeke giran were rastkirin an pêşî lê were girtin, bi erêkirineke zûtir a li gorî wê.","also":["emergency changes","emergency change","guhertinên acîl"]},{"id":"automation","g":"change","word":"Otomasyon","text":"Kirina ku komputer karekî dubarekirî bi xwe bike, da ku zûtir be û her carê heman awayî were kirin.","also":["automated","automation","otomasyon"],"noTip":1},{"id":"infra","g":"change","word":"Binesaz (infrastructure)","text":"Makîne, tor û xizmetên ku nermalav li ser dixebite.","also":["infra","infrastructure","binesaz"]},{"id":"iac","g":"change","word":"Infrastructure as code (IaC)","text":"Danasîna server û mîhengên xwe di pelan de ku bi kodê re tên girtin, da ku her carê tam bi heman awayî dîsa bêne avakirin.","also":["IaC"]},{"id":"cloud","g":"change","word":"Cloud (ewr)","text":"Bi kirê girtina komputer, hilanîn û xizmetan ji pêşkêşkerekî mezin bi rêya înternetê, li şûna ku tu bi xwe xwediyê makîneyan bî.","also":["the cloud","cloud computing","cloud","ewr"]},{"id":"provider","g":"change","word":"Cloud provider","text":"Şirketeke ku hêza komputeran bi rêya înternetê bi kirê dide, mînak Amazon Web Services (AWS), Microsoft Azure an Google Cloud.","also":["cloud providers","cloud provider"]},{"id":"hosting","g":"change","word":"Hosting","text":"Cihê ku app an malpera te lê dijî û dixebite da ku mirov bigihîjin wê, bi gelemperî ji şirketekê bi kirê hatiye girtin.","also":["hosting"]},{"id":"domain","g":"change","word":"Navê domainê","text":"Navnîşana webê ya ku mirov dinivîsin, mîna example.com. Tu wê salane bi kirê digirî, loma divê were nûkirin.","also":["domain names","domain","navê domainê"]},{"id":"dns","g":"change","word":"DNS","text":"Kurtkirina domain name system: pirtûka navnîşanan a înternetê, ku navekî mîna example.com dike navnîşana komputerê rast.","also":["domain name system"]},{"id":"container","g":"change","word":"Container","text":"Pakêteke girtî ku appekê û her tiştê wê hewce dike dihewîne, da ku li ser her komputerê heman awayî bixebite. Docker amûra herî naskirî ye.","also":["containers","Docker","container"],"noTip":1},{"id":"vm","g":"change","word":"Virtual machine (VM)","text":"Komputerekî xeyalî ku di nav yekî rast de dixebite, da ku makîneyeke mezin wekî gelek makîneyan tevbigere.","also":["VM","VMs","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless","text":"Xebitandina kodê bêyî ku tu bi xwe li tu serverî miqate bibî: pêşkêşker gava hewce be wê dimeşîne û tu tenê pereyê tiştê ku bi kar tînî didî."},{"id":"lb","g":"change","word":"Load balancer","text":"Tiştekî ku serdanvanan di nav çend serveran de par ve dike, da ku tu yek ji wan zêde bar nebe.","also":["load balancers","load balancer"]},{"id":"cache","g":"change","word":"Cache","text":"Embareke bikêr a encamên dawî ku nêzîk tên girtin, da ku ne hewce be heman tişt dîsa were anîn an hesabkirin. Paqijkirina wê dikare rûpelên ku kevn xuya dikin rast bike.","also":["caches","caching","cached","cache"]},{"id":"cdn","g":"change","word":"Content delivery network (CDN)","text":"Komeke serverên li seranserê cîhanê ku kopiyên rûpel û wêneyên te nêzîkî serdanvanan digirin, da ku zû bêne barkirin.","also":["CDN"]},{"id":"migration","g":"change","word":"Migration (koçberî)","text":"Veguhastina daneyan an pergalan ji sazkirineke kevn bo ya nû, an guhertina bi baldarî ya rêkxistina databaseyekê.","also":["migrations","database migration","migration","koçberiya databaseê"]},{"id":"service","g":"run","word":"Xizmet","text":"Tiştek ku te ava kiriye û mirov pê bawer dikin, wek malperek an sepanek, ku lê tê miqatekirin da ku bixebite. \"Ev proje xizmetek e\" nîşan bike û bibêje ka ew çi pêşkêş dike, kî bi kar tîne û kî bersivdar e.","also":["xizmet","service"]},{"id":"uptimepct","g":"run","word":"Uptime","text":"Xizmetek çiqas ji demê dixebite, bi gelemperî wekî sedî. %99,9 jî destûrê dide ku xizmet di mehekê de nêzîkî 43 xulekan rawestiyayî be.","also":["uptime percentage","uptime"]},{"id":"uptime","g":"run","word":"Kontrola xebitînê","text":"Kontroleke otomatîk, her çend deqeyan carekê, ka xizmeta te hîn bersiv dide. Heke çend caran li pey hev têk biçe, AI-gile bi xwe karteke bûyerê vedike.","also":["uptime checks","kontrolên uptime"]},{"id":"statuspage","g":"run","word":"Rûpela statûyê","text":"Rûpeleke giştî ku nîşan dide ka xizmetek dixebite (kesk, porteqalî an sor) bi nûçeya dawî re, da ku kesên ku bi kar tînin li wir binêrin li şûna pirsînê.","also":["rûpelên statûyê","status page"]},{"id":"desk","g":"run","word":"Maseya xizmetê","text":"Cihê ku pirs û raporên kesên ku xizmeta te bikar tînin lê tên. AI-gile her yekê wekî daxwaz, bûyer an fikir rêz dike, û dibêje heke ew dişibe tiştekî ku berê hatiye ragihandin.","also":["maseyên xizmetê","maseya alîkariyê","help desk"]},{"id":"svcrequest","g":"run","word":"Daxwaza xizmetê","text":"Kesek tiştekî asayî dixwaze, wekî hesabekî nû an hinek alîkarî, ne ku ragihîne ku tiştek şikestiye. Ew li benda dora xwe dimîne; bûyer pêşî tê.","also":["daxwazên xizmetê","daxwaz"]},{"id":"incident","g":"run","word":"Bûyer","text":"Tiştek ku ji bo kesên wê niha bi kar tînin şikestî ye an rast naxebite, mîna ku malper daketî ye an pir hêdî ye. Karta 🔥 bûyerê rêzê derbas dike: dîsa xebitandina wê pêşî tê.","also":["bûyera acîl","bûyer","incident"]},{"id":"major","g":"run","word":"Bûyera mezin","text":"Bûyereke mezin: gelek kes bandor bûne, an pere an dane di xeterê de ne. Bişkokek hemû tîman dide ser wê (swarm), kesê bersivdar şiyar dike û her 30 deqeyan nûkirineke statûyê dixwaze.","also":["bûyerên mezin","major incident"]},{"id":"oncall","g":"run","word":"Bersivdarî","text":"Bûna kesê ku bersiv dide dema tiştek dişkê, şevê jî. Her xizmetekê endamekî tîmê yê bersivdar heye ku ji bo bûyerên wê pêşî tê şiyarkirin.","also":["bersivdar","on call","on-call"]},{"id":"replyby","g":"run","word":"Dema bersivdanê","text":"Kartek çiqas dikare li benda bersiva yekem bimîne, mînak saetek ji bo bûyerekê. Piştî wê saeteke sor distîne, da ku tiştek bi bêdengî neyê jibîrkirin. Jê re armanca bersivdanê jî tê gotin.","also":["demên bersivdanê","armanca bersivdanê","response target"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"Nihêrîneke kurt a paşve piştî bûyerekê: çi qewimî, çi alîkarî kir û çi divê were guhertin, bêyî ku kes were sûcdarkirin. Bêyî wê bûyer nayê girtin.","also":["post-mortem","postmortem","nirxandina piştî bûyerê"]},{"id":"problem","g":"run","word":"Pirsgirêk","text":"Sedema veşartî ya li pişt yek an çend bûyeran. Karta 🧩 pirsgirêkê bûyerên ku dîsa û dîsa vedigerin kom dike, da ku sedem were dîtin û bi carekê were rastkirin.","also":["pirsgirêk","problem"],"noTip":1},{"id":"rootcause","g":"run","word":"Sedema bingehîn","text":"Sedema rastîn a ku tiştek şikest, ne tenê ya ku te dît xelet diçe. Sedema bingehîn rast bike û bûyer êdî venagere.","also":["sedemên bingehîn","root cause"]},{"id":"workaround","g":"run","word":"Çareya demkî","text":"Rêyek ji bo xebitandina tiştan heta ku rastkirina rastîn amade bibe, wek ji nû ve destpêkirina tiştekî dema ku asê dibe. Ew li ser karta pirsgirêkê tê nivîsandin da ku kes neçar nemîne dîsa bibîne.","also":["çareyên demkî","workaround"]},{"id":"knownerror","g":"run","word":"Çewtiya nas","text":"Pirsgirêkeke ku sedema wê tê zanîn lê hê nehatiye rastkirin, bi gelemperî bi çareyeke demkî ya nivîsandî. 🧩 Çewtiyên nas wan lîste dike, da ku her kes çareya demkî bi kar bîne li şûna ku dîsa bikole.","also":["çewtiyên nas","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Rêwerzên gav bi gav ji bo rastkirina cureyekî nas ê pirsgirêkê, da ku her car bi heman awayî û bilez were kirin. Piştî bûyereke mezin tîm dikare yekê pêşniyar bike ku tu OK bikî.","also":["runbook","rêbernameya karan"]},{"id":"ci","g":"run","word":"Tiştê mîhengê","text":"Tiştek ku xizmeta te pê ve girêdayî ye, wekî server, domain, sertîfika, kilît an dabînker. 🗂️ Tiştên mîhengê wan li gorî xizmetê rêz dike, da ku tu bibînî bûyerek bandorê li çi dike û çi divê bê nûkirin an kopîkirin.","also":["tiştên mîhengê","tiştê mîhengkirinê"]},{"id":"expiry","g":"run","word":"Dîroka qedandinê","text":"Roja ku tiştek êdî nexebite heke neyê nûkirin, mîna sertîfîkaya ewlehiyê ya malperekê an navnîşana wê ya webê. AI-gile van rojan dişopîne û 30 roj berê ji bo nûkirina her yekê kartek çêdike, da ku tu tişt ji nişka ve nesekine.","also":["dîrokên qedandinê","qedandin","çavdêriya qedandinê"]},{"id":"backup","g":"run","word":"Kopiya ewlehiyê","text":"Kopiyeke tomarkirî ya daneyên te yên berê, ji bo ku pê bikevî heke tiştek winda bibe an xera bibe. AI-gile her roj kopiyeke ewlehiyê ya panoyên te çêdike.","also":["backup","kopî","kopiyên ewlehiyê"]},{"id":"restore","g":"run","word":"Vegerandina daneyan","text":"Daneyan ji kopiya ewlehiyê paşde danîn. Kopiyek tenê dema ku tu dizanî dikare were vegerandin bi rastî tê hesibandin, ji ber vê yekê hêja ye ku carinan biceribînî.","also":["vegerîne","restore"]},{"id":"svcreview","g":"run","word":"Nirxandina xizmetê","text":"Nêrînek li mehekê ya xizmetekê: bûyerên ku vebûn û hatin çêkirin, mirov çiqas zû bersiv wergirtin, dema xebitînê û tokenên ku hatin bikaranîn. Nirxandina mehane vê ji bo her xizmetê nîşan dide.","also":["nirxandinên xizmetê","nirxandina mehane","nirxandinên mehane"]},{"id":"accessreview","g":"run","word":"Vekolîna gihîştinê","text":"Kontrolkirina her 90 rojan ka kî hê dikare têkeve: lînkên parvekirinê, rolên hevalan û şîfre û kilîtên tomarkirî. Tu her yekê dihêlî an radikî, da ku gihîştina kevn nemîne.","also":["vekolînên gihîştinê","vekolîna destpêgihîştinê"]},{"id":"improvements","g":"run","word":"Lîsteya baştirkirinan","text":"Her tiştê ku tîmê biryar da ku tê de baştir bibe, li yek cihî: pêşniyarên retro, kiryarên nirxandinê û çareyên pirsgirêkan, her yek bi rewşa xwe. Wê di bin 📈 Baştirkirin de bibîne.","also":["lîsteyên baştirkirinan","baştirkirin"]},{"id":"tokencap","g":"run","word":"Sînora tokenan","text":"Sînoreke mehane ya tokenên ku ajanên xizmetekê dikarin bikar bînin. Li 80% tu hişyariyekê distînî; li 100% xebata wan a paşxaneyê heta meha bê an heta ku tu sînorê bilind bikî li bendê dimîne.","also":["sînorên tokenan","sînora tokenên mehane"]},{"id":"svcmgmt","g":"run","word":"Rêvebirina xizmetê","text":"Her tiştê pêwist ji bo ku xizmetek roj bi roj ji kesên pê bawer dikin re bikêrhatî û xebatdar bimîne.","also":["service management"]},{"id":"itil","g":"run","word":"ITIL","text":"Rêberek ku pir tê bikaranîn ji bo rêvebirina baş a xizmetê, ku tiştên mîna bûyer, pirsgirêk û guhertinan dihewîne. Navê wê berê kurtkirina IT Infrastructure Library bû."},{"id":"itsm","g":"run","word":"Rêvebirina xizmeta IT (ITSM)","text":"Xebitandina teknolojiyê wekî xizmetek ji bo mirovan, bi awayên zelal ji bo birêvebirina daxwaz, bûyer, guhertin û başkirinan.","also":["ITSM"]},{"id":"managed","g":"run","word":"Managed service","text":"Xizmeteke ku kesekî din ji bo te dimeşîne û lê miqate dibe, li gorî lihevkirinekê ku divê çiqas baş bixebite.","also":["managed services","managed service"]},{"id":"svcowner","g":"run","word":"Xwediyê xizmetê","text":"Kesê ku ji bo xizmetê wekî giştî berpirsiyar e: çiqas baş dixebite, çiqas lê diçe û çawa baştir dibe.","also":["service owners","service owner","xwediyên xizmetê"]},{"id":"sla","g":"run","word":"Service level agreement (SLA)","text":"Sozeke nivîskî ji xerîdaran re ku xizmetek dê çiqas baş bixebite, mîna “%99,9ê demê dixebite” an “di nav saetekê de bersiv”, pir caran bi vegerandina pereyan heke soz were şikandin.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Service level objective (SLO)","text":"Armanca xwe ya tîmê ku xizmetek di heyamekê de divê çiqas baş bixebite, bi gelemperî hinekî ji SLA tundtir tê danîn ji bo ewlehiyê.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Service level indicator (SLI)","text":"Pîvana rast ku tu li hemberî armancekê kontrol dikî, mînak beşa serdanên ku baş barkirin.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Peydabûn (availability)","text":"Gelo mirov dikarin xizmetekê gava hewce dikin bi kar bînin, pir caran wekî uptime tê pîvandin.","also":["high availability","availability","peydabûn"]},{"id":"downtime","g":"run","word":"Downtime (dema rawestanê)","text":"Dema ku xizmet naxebite an hatiye girtin, plankirî be an na.","also":["down time","downtime","dema rawestanê"]},{"id":"errorbudget","g":"run","word":"Error budget","text":"Mîqdara biçûk a têkçûnê ku armanca te ya pêbaweriyê destûr dide. Heta ku hinek jê mabe tu dikarî di guhertinan de xeterê bidî ber çavan; gava biqede, tu hêdî dibî.","also":["error budgets","error budget"]},{"id":"outage","g":"run","word":"Outage (qutbûn)","text":"Dema ku xizmet ji bo bikarhêneran daketî an bi giranî şikestî ye.","also":["outages","outage","qutbûn"]},{"id":"degraded","g":"run","word":"Degraded (kêmbûyî)","text":"Dixebite, lê xirab: hêdî ye, an hin beşên wê naxebitin.","also":["degraded service","degraded","kêmbûyî"]},{"id":"monitoring","g":"run","word":"Monitoring (çavdêrî)","text":"Şopandina xizmetekê her dem û bi otomatîk, da ku pirsgirêk bêne dîtin, ya herî baş beriya ku bikarhêner pê bihesin.","also":["monitoring","çavdêrî"]},{"id":"observability","g":"run","word":"Observability","text":"Tu çiqas dikarî ji derve bizanî ka di hundirê pergalekê de çi diqewime, bi bikaranîna log, hejmar û traceyên wê.","also":["o11y","observability"]},{"id":"log","g":"run","word":"Log","text":"Rojnivîskeke berdewam a ku bernameyek li ser tiştê ku dike digire, ji bo fêmkirina ka çi şaş çû tê bikaranîn.","also":["logs","logging","log"],"noTip":1},{"id":"trace","g":"run","word":"Trace","text":"Qeydeke ku daxwazek çawa gav bi gav di nav beşên cuda yên pergalê re diçe, û nîşan dide li ku hêdî bû.","also":["traces","tracing","trace"]},{"id":"latency","g":"run","word":"Latency (derengî)","text":"Bersivdana tiştekî çiqas dem digire, mîna benda di navbera bitikandinê û xuyabûna rûpelê de.","also":["latency"]},{"id":"alert","g":"run","word":"Alert (hişyarî)","text":"Peyamek otomatîk ku tiştek baldariyê hewce dike, mîna ku malper bersiv nade.","also":["alerts","alerting","alert","hişyarî"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Alert fatigue (westandina ji hişyariyan)","text":"Gava ewqas hişyarî hene ku mirov dest pê dikin hemûyan paşguh bikin, yên girîng jî.","also":["alarm fatigue","alert fatigue","westandina ji hişyariyan"]},{"id":"dashboard","g":"run","word":"Dashboard","text":"Dîmenek ku hejmar û rewşên herî girîng bi yek nihêrînê nîşan dide.","also":["dashboards","dashboard"],"noTip":1},{"id":"paging","g":"run","word":"Paging","text":"Bangkirin an şiyarkirina lezgîn a kesê nobedar (on-call) ji ber pirsgirêkekê.","also":["paged","paging"]},{"id":"escalation","g":"run","word":"Escalation (bilindkirin)","text":"Anîna kesekî bi jêhatîbûn an desthilatdariya zêdetir gava pirsgirêk li asta heyî nayê çareserkirin, an ne têra xwe zû.","also":["escalate","escalated","escalation","bilindkirin"]},{"id":"triage","g":"run","word":"Triage","text":"Rêzkirina zû ya pirsgirêkên ku tên li gorî lezgînî û girîngiyê, da ku ya herî xirab pêşî were birêvebirin.","also":["triaged","triage"]},{"id":"impact","g":"run","word":"Bandor","text":"Tiştek çiqas bandorê li mirovan dike: çend kes, û çiqas xirab.","noTip":1},{"id":"urgency","g":"run","word":"Lezgînî","text":"Tiştek çiqas zû divê were birêvebirin. Bandor û lezgînî bi hev re pêşîniyê diyar dikin.","noTip":1},{"id":"plevels","g":"run","word":"Astên pêşîniyê (P1, P2…)","text":"Nîşanên ku dibêjin pirsgirêkek çiqas lezgîn e. P1 ya herî giran e û tavilê çalakî hewce dike.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Rêza ticketan","text":"Lîsteya daxwaz û bûyerên ku li benda hilgirtinê ne.","also":["rêzên ticketan","ticket queues","ticket queue"]},{"id":"tiers","g":"run","word":"Xeta yekem û xeta duyem","text":"Astên piştgiriyê: xeta yekem bangê werdigire û tiştên hêsan rast dike; xeta duyem xwedî jêhatîbûna kûrtir e ji bo yên dijwartir. Jê re tier 1 û tier 2 jî tê gotin.","also":["xeta yekem","xeta duyem","first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Incident commander (fermandarê bûyerê)","text":"Kesê yekane yê ku bersivdana bûyerekê birêve dibe, da ku her kes bizane kî biryar dide û kî çi dike.","also":["incident commanders","incident commander","fermandarê bûyerê"]},{"id":"responsetime","g":"run","word":"Dema bersivdanê","text":"Çiqas dem diçe heta ku kesek cara yekem daxwazek an bûyerekê hildide.","also":["response times","response time","demên bersivdanê"]},{"id":"resolution","g":"run","word":"Dema çareseriyê","text":"Çiqas dem digire ku daxwazek an bûyerek bi temamî were çareserkirin, ji raporê heta rastkirinê.","also":["resolution times","time to resolve","resolution time","demên çareseriyê"]},{"id":"mttr","g":"run","word":"Mean time to recover (MTTR)","text":"Bi navînî, çiqas dem digire ku xizmetek piştî şikestinê dîsa bixebite. MTTR dikare wateyên hinekî cuda hebin, loma bibêje tu çi dipîvî.","also":["MTTR","mean time to restore"]},{"id":"mtbf","g":"run","word":"Mean time between failures (MTBF)","text":"Bi navînî, xizmetek berî ku tiştek bişkê çiqas dem dixebite.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Configuration management database (CMDB)","text":"Lîsteya hemû hêmanên te yên mîhengê (configuration items) û çawa bi hev ve girêdayî ne, da ku tu bibînî çi bi çi ve girêdayî ye.","also":["CMDB"]},{"id":"asset","g":"run","word":"Asset (saman)","text":"Her tiştê bi nirx ku tu xwedî dikî an ji bo birêvebirina xizmetê pere didî, mînak laptopek, lîsansa nermalavê an domainek.","also":["assets","asset","saman"],"noTip":1},{"id":"capplan","g":"run","word":"Plankirina kapasîteyê","text":"Piştrastkirina ku ji bo tiştê tê têra hêza komputerê, hilanîn û mirov hebe.","also":["capacity plan","capacity planning","plana kapasîteyê"]},{"id":"scaling","g":"run","word":"Scaling (mezinkirin)","text":"Birêvebirina bikarhênerên zêdetir bi dayîna hêza zêdetir ji makîneyekê re (scale up) an zêdekirina makîneyên din (scale out).","also":["scale up","scale out","scaling up","scaling out","scaling","mezinkirin"]},{"id":"bcp","g":"run","word":"Berdewamiya karsaziyê","text":"Plan ji bo domandina tiştên girîng gava tiştekî mezin xirab diçe, mîna windakirina nivîsgehekê, peydakerekî sereke an komputeran.","also":["business continuity plan","business continuity","plana berdewamiya karsaziyê"]},{"id":"dr","g":"run","word":"Disaster recovery (DR) (vegera ji karesatê)","text":"Plan û amûr ji bo vegerandina xizmetekê piştî tiştekî giran, mîna windakirina tevahiya navendeke daneyan.","also":["disaster recovery","vegera ji karesatê"]},{"id":"rto","g":"run","word":"Recovery time objective (RTO)","text":"Dema herî dirêj ku xizmetek piştî karesatekê dikare daketî be berî ku divê dîsa bixebite.","also":["RTO"]},{"id":"rpo","g":"run","word":"Recovery point objective (RPO)","text":"Tu dikarî çiqas daneyên nû ji dest bidî, bi demê tê pîvandin. RPOya saetekê tê wê wateyê ku herî kêm her saet yedek tê girtin.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Redundancy (yedekî)","text":"Amadehiştina yedekan, mîna serverekî duyem, da ku yek têkçûn xizmetê nesekinîne.","also":["redundancy","yedekî"]},{"id":"failover","g":"run","word":"Failover","text":"Derbasbûna bi xwe bo pergaleke yedek gava pergala asayî têk diçe.","also":["fail over","failover"]},{"id":"spof","g":"run","word":"Xala yekane ya têkçûnê","text":"Beşek ku gava dişkê her tiştî bi xwe re dixîne, ji ber ku yedek tune ye.","also":["single points of failure","SPOF","single point of failure"]},{"id":"maintwin","g":"run","word":"Maintenance window (demjimêra lênihêrînê)","text":"Dema plankirî ku xizmetek dikare ji bo lênihêrînê were rawestandin an hêdî bibe, ji bikarhêneran re pêşwext tê ragihandin.","also":["maintenance windows","planned maintenance","demjimêra lênihêrînê"]},{"id":"handover","g":"run","word":"Handover (radestkirin)","text":"Radestkirina xebat, zanîn û berpirsiyariyê ji kesekî an tîmekî din re, da ku tu tişt winda nebe.","also":["handovers","handover","radestkirin"]},{"id":"kb","g":"run","word":"Knowledge base (bingeha zanînê)","text":"Berhevoka gotarên alîkariyê û bersivan, ji bo bikarhêner û tîmê.","also":["knowledge bases","knowledge base","bingeha zanînê"]},{"id":"csat","g":"run","word":"Customer satisfaction (CSAT)","text":"Pûaneke ku bikarhêner dibêjin çiqas kêfxweş bûn, pir caran piştî girtina daxwazekê tê pirsîn.","also":["CSAT"]},{"id":"supplier","g":"run","word":"Peydaker (supplier)","text":"Şirketeke derve ku tu pê ve girêdayî yî, mînak peydakerê te yê hostingê. Jê re vendor an aliyê sêyem jî tê gotin.","also":["suppliers","vendor","vendors","third party","peydaker","aliyê sêyem"],"noTip":1},{"id":"retire","g":"run","word":"Service retirement (teqawîdkirina xizmetê)","text":"Vemirandina xizmetekê ji bo her tim, bi ewlehî: ragihandina bikarhêneran, birêvebirina daneyên wê û gihîştina wê, û rawestandina lêçûnên wê.","also":["retiring a service","service retirement","teqawîdkirina xizmetê"]},{"id":"eol","g":"run","word":"End of life (EOL) (dawiya temenê)","text":"Gava ku hilberek êdî ji çêkerê xwe nûkirin an piştgiriyê nastîne, loma divê tiştekî din li şûna wê were danîn.","also":["EOL","end-of-life","end of life","dawiya temenê"]},{"id":"cybersec","g":"sec","word":"Ewlehiya sîber","text":"Parastina pergal û daneyan ji ketina hundir a bê destûr, dizîn an zirarê.","also":["cyber security","cybersecurity","ewlehiya sîber"]},{"id":"authn","g":"sec","word":"Authentication (piştrastkirina nasnameyê)","text":"Kontrolkirina ka kesek kî ye, bi gelemperî bi şîfre an kodekê. Pir caran wekî authn tê kurtkirin.","also":["authn","authentication","piştrastkirina nasnameyê"]},{"id":"authz","g":"sec","word":"Authorisation (destûrdan)","text":"Kontrolkirina ka kesek destûra wî heye çi bike, piştî ku tu dizanî ew kî ye. Pir caran wekî authz tê kurtkirin.","also":["authz","authorization","authorisation","destûrdan"]},{"id":"mfa","g":"sec","word":"Piştrastkirina bi gelek faktoran (MFA)","text":"Têketin bi du an zêdetir delîlan, mîna şîfre û kodeke li ser têlefona te. Jê re du-faktor (2FA) jî tê gotin.","also":["MFA","2FA","two-factor","two-factor authentication","piştrastkirina du-faktorî"]},{"id":"sso","g":"sec","word":"Single sign-on (SSO)","text":"Carekê têketin da ku têkevî gelek pergalan, mîna bikaranîna hesabê xebata xwe li her derê.","also":["SSO"]},{"id":"pwmgr","g":"sec","word":"Password manager (rêvebirê şîfreyan)","text":"Appek ku şîfreyên bihêz çêdike û ji bo te tomar dike.","also":["password managers","password manager","rêvebirê şîfreyan"]},{"id":"secret","g":"sec","word":"Secret (nepenî)","text":"Şîfre, kilît an kodeke din a taybet ku bernameyek ji bo têketina tiştekî bi kar tîne. Divê tu carî neyê parvekirin an di kodê de were nivîsandin.","also":["secrets","secret","nepenî"],"noTip":1},{"id":"apikey","g":"sec","word":"Kilîta API","text":"Koda nepenî ya ku dihêle bernameyek API ya xizmeteke din bi kar bîne, û nîşan dide kî wê bi kar tîne (û pere dide).","also":["API keys","API key","kilîta API"]},{"id":"accesstoken","g":"sec","word":"Access token","text":"Derbasnameyeke demkî ku îspat dike bernameyek destûra têketinê heye, da ku her carê hewceyî şîfreya te nebe. Ne wekî tokena AI ye.","also":["access tokens","access token"]},{"id":"encryption","g":"sec","word":"Şîfrekirin (encryption)","text":"Tevlihevkirina agahiyan da ku tenê kesê bi kilîta rast bikaribe bixwîne.","also":["encrypted","encrypt","encryption","şîfrekirin"]},{"id":"https","g":"sec","word":"HTTPS","text":"Awayê ewle yê ku rûpelên webê pê digerin, bi qefla di geroka te de tê nîşandan, da ku kes di navberê de nikaribe wan bixwîne an biguherîne."},{"id":"cert","g":"sec","word":"Sertîfîkaya SSL/TLS","text":"Karta nasnameyê ya dîjîtal a ku dihêle malperek îspat bike kî ye û HTTPS bi kar bîne. Dem lê diqede, loma divê were nûkirin.","also":["TLS certificate","SSL certificate","certificate","certificates","sertîfîka"]},{"id":"permissions","g":"sec","word":"Destûr (permissions)","text":"Rêzikên ku diyar dikin kî dikare çi bibîne an biguherîne.","also":["permission","permissions","destûr"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Least privilege (kêmtirîn îmtiyaz)","text":"Dayîna her kesî an her bernameyê tenê ew gihîştina ku bi rastî hewce dike, û tenê heta ku hewce dike.","also":["principle of least privilege","least privilege","kêmtirîn îmtiyaz"]},{"id":"rbac","g":"sec","word":"Role-based access control (RBAC)","text":"Dayîna gihîştinê li gorî rolê, mîna temaşevan an edîtor, li şûna kes bi kes.","also":["RBAC","role-based access"]},{"id":"vuln","g":"sec","word":"Qelsî (vulnerability)","text":"Qelsiyeke ku kesek dikare bi kar bîne da ku têkeve an zirarê bide.","also":["vulnerabilities","vulnerability","qelsî"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"Qelsiyeke ku êrîşkar jê haydar in beriya ku çêkeran tu dem hebûbe ku wê rast bikin.","also":["zero-days","zero day","zero-day"]},{"id":"malware","g":"sec","word":"Malware (nermalava xirab)","text":"Nermalava zirardar, mîna vîrusan, ji bo zirardan, sîxuriyê an dizînê hatiye çêkirin.","also":["malware","nermalava xirab"]},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malwareyek ku pelên te qefl dike û ji bo vekirina wan pere dixwaze. Yedekên baş parastina herî baş in.","also":["ransomware attack","ransomware"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Peyamên sexte yên ku hewl didin te bixapînin da ku tu şîfre an pere bidî, an tiştekî zirardar vekî.","also":["phishing email","phishing emails","phishing"]},{"id":"socialeng","g":"sec","word":"Social engineering (endezyariya civakî)","text":"Xapandina mirovan, ne komputeran, ji bo gihîştinê, mîna bangeke sexte ji “piştgiriya IT”."},{"id":"firewall","g":"sec","word":"Firewall","text":"Parêzvanek ku biryar dide kîjan trafîka torê dikare bê hundir an derkeve.","also":["firewalls","firewall"]},{"id":"vpn","g":"sec","word":"VPN","text":"Kurtkirina virtual private network: girêdaneke taybet û şîfrekirî bi rêya înternetê, pir caran ji bo gihîştina bi ewlehî bi pergalên xebatê tê bikaranîn.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"Denial of service (DoS, DDoS)","text":"Tijîkirina xizmetekê bi trafîkeke sexte ya ewqas zêde ku mirovên rast nikaribin wê bi kar bînin. DDoS tê wê wateyê ku ji gelek komputeran di heman demê de tê.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Penetration test (pen test)","text":"Girtina pisporên dostane da ku hewl bidin têkevin, da ku qelsî werin dîtin beriya ku êrîşkarên rast wan bibînin.","also":["pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Auditkirina ewlehiyê","text":"Kontroleke baldar a ku tiştek çiqas baş hatiye parastin, li hemberî lîsteyeke pratîkên baş.","also":["security audits","security audit","auditkirina ewlehiyê"]},{"id":"threatmodel","g":"sec","word":"Threat modelling (modelkirina gefan)","text":"Fikirîn li ser ka kî dikare êrîşî tiştekî bike, çawa, û tu dê çi bikî da ku wan rawestînî.","also":["threat model","threat modeling","threat modelling","modelkirina gefan"]},{"id":"breach","g":"sec","word":"Data breach (derketina daneyan)","text":"Gava ku agahiyên taybet digihîjin kesên ku nabe bigihîjin wan, an bêyî destûr winda dibin an tên guhertin.","also":["data breaches","data breach","derketina daneyan"]},{"id":"pii","g":"sec","word":"Daneyên kesane","text":"Her agahiyek li ser kesekî ku dikare were nasîn, mîna nav, navnîşana e-nameyê an cih. Jê re PII jî tê gotin.","also":["PII","personally identifiable information","daneyên kesane"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"Qanûna Ewropayê ya li ser daneyên kesane (Brîtanyayê guhertoya xwe heye): tenê tiştê hewce berhev bike, ewle biparêze, û bihêle mirov yên xwe bibînin an jê bibin.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Parastina daneyan","text":"Lênihêrîna rast a daneyên kesane û di nav qanûnê de.","also":["data protection law","data protection","qanûna parastina daneyan"]},{"id":"privacypolicy","g":"sec","word":"Siyaseta nepenîtiyê","text":"Rûpeleke giştî ya ku dibêje tu kîjan daneyên kesane berhev dikî, çima, û tu çi pê dikî.","also":["privacy statement","privacy notice","privacy policy","daxuyaniya nepenîtiyê"]},{"id":"consent","g":"sec","word":"Razîbûn (consent)","text":"“Erê”ya zelal û azad a kesekî ji bo bikaranîna daneyên wî bi awayekî taybet. Ew dikare her dem razîbûna xwe paşve bigire.","also":["opt-in","consent","razîbûn"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie (kûkî)","text":"Pelekî biçûk ku malperek di geroka te de tomar dike da ku tiştan bi bîr bîne, mîna ku tu têketî yî. Hin ji wan pêşî razîbûna te hewce dikin.","also":["cookies","cookie","kûkî"],"noTip":1},{"id":"minimisation","g":"sec","word":"Data minimisation (kêmkirina daneyan)","text":"Tenê berhevkirin û girtina daneyên kesane yên ku bi rastî ji bo kar pêwîst in.","also":["data minimization","data minimisation","kêmkirina daneyan"]},{"id":"retention","g":"sec","word":"Data retention (girtina daneyan)","text":"Dane çiqas dem tên girtin berî ku werin jêbirin. Girtina wan ne ji ya hewce dirêjtir ewletir e û pir caran qanûn jî wisa dixwaze.","also":["retention period","data retention","girtina daneyan"]},{"id":"anon","g":"sec","word":"Anonymisation (bênavkirin)","text":"Guhertina daneyan da ku êdî kes bi maqûlî ji wan neyê nasîn.","also":["anonymised","anonymization","anonymous data","anonymisation","bênavkirin"]},{"id":"pseudo","g":"sec","word":"Pseudonymisation (nasnavkirin)","text":"Guhertina nav û hûrgiliyên din bi kodan, bi kilîteke ku cuda tê parastin da ku wan dîsa bi hev ve girêbide. Hê jî daneya kesane ye.","also":["pseudonymised","pseudonymization","pseudonymisation","nasnavkirin"]},{"id":"dpa","g":"sec","word":"Data processing agreement (DPA)","text":"Peymanek ku dibêje peydakerek dikare daneyên kesane li şûna te çawa bi kar bîne.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Data protection impact assessment (DPIA)","text":"Nihêrîneke baldar, beriya destpêkirinê, ku plana bikaranîna daneyên kesane dikare çawa bandorê li mirovan bike û xeterî çawa werin kêmkirin.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Audit log","text":"Qeydeke ku kê çi kir û kengê, da ku kar paşê werin kontrolkirin.","also":["audit logs","audit trail","audit log"]},{"id":"compliance","g":"sec","word":"Compliance (lihevhatin)","text":"Şopandina qanûn, rêzik û standardên ku ji bo te derbasdar in, û karîna nîşandana ku tu wan dişopînî.","also":["compliant","compliance","lihevhatin"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Standardeke navneteweyî ya navdar ji bo rêvebirina ewlehiya agahiyan. Şirket dikarin li gorî wê sertîfîkayê bistînin.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Raporeke Amerîkayê, ji aliyê kontrolkerên derve ve hatiye kontrolkirin, ku nîşan dide şirketek bi rastî li daneyên xerîdaran miqate dibe.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agent","text":"AIyeke ku bi tena serê xwe li ser karekî dixebite: kodê dixwîne, guhertinan dike, kontrolan dimeşîne û rapor dide. Xebata wê hê jî tê kontrolkirin.","also":["agents"]},{"id":"token","g":"ai","word":"Token","text":"Perçeyên biçûk ên nivîsê yên ku AI dixwîne û dinivîse, her yek nêzîkî sê çaryekên peyvekê. Bikaranîna AI bi token tê hejmartin, loma tokenên kêmtir zêdetir ji plana te dihêlin.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"Fermanek biçûk ku di kêliyeke diyarkirî de bi xwe dimeşe, mînak gava sessionek AI dest pê dike, da ku tîm şîroveyên te bibihîze.","also":["hooks"]},{"id":"ai","g":"ai","word":"Zîrekiya çêkirî (AI)","text":"Pergalên komputerê yên ku karên ku em bi gelemperî difikirin mirovek ji bo wan hewce ye dikin, mîna nivîsandin, bersivdana pirsan an nasîna wêneyan.","also":["AI","artificial intelligence","zîrekiya çêkirî"],"noTip":1},{"id":"ml","g":"ai","word":"Machine learning (ML) (fêrbûna makîneyê)","text":"Awayek ji bo ku komputer ji gelek mînakan şêweyan fêr bibin, li şûna ku rêzikên tam bidin wan.","also":["machine learning","fêrbûna makîneyê"]},{"id":"model","g":"ai","word":"Model","text":"“Mejiyê” perwerdekirî yê pergaleke AI, bi fêrbûna ji hejmareke mezin a mînakan hatiye çêkirin. Model di jêhatîbûn, lez û bihayê xwe de ji hev cuda ne.","also":["models","AI model","modela AI"],"noTip":1},{"id":"llm","g":"ai","word":"Large language model (LLM) (modela zimanî ya mezin)","text":"Modeleke AI ya ku li ser mîqdareke mezin a nivîsê hatiye perwerdekirin, loma dikare ziman bixwîne û binivîse.","also":["LLM","LLMs","modela zimanî ya mezin"]},{"id":"genai","g":"ai","word":"AI ya çêker (Generative AI)","text":"AI ya ku tiştên nû çêdike, mîna nivîs, wêne an kod, li şûna ku tenê wan rêz bike an nas bike.","also":["GenAI","Generative AI","AI ya çêker"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"Bernameyek ku tu bi zimanê rojane bi wê re diaxivî, bi nivîsandin an axaftinê.","also":["chatbots","chatbot"]},{"id":"prompt","g":"ai","word":"Prompt","text":"Tiştê ku tu didî AI: pirs an rêwerzên te, û her tiştê ku didî destê wê. Promptên zelaltir bi gelemperî bersivên baştir distînin.","also":["prompts","prompt"]},{"id":"prompteng","g":"ai","word":"Prompt engineering","text":"Jêhatîbûna nivîsandina promptan ku encamên pêbawer û bikêr distînin.","also":["prompt engineering"]},{"id":"sysprompt","g":"ai","word":"System prompt","text":"Rêwerzên paşxanê yên ku AI beriya destpêkirina sohbetê distîne, rol û rêzikên wê diyar dikin. Ji tiştê tu dinivîsî girantir in.","also":["system prompts","system instruction","system instructions","system prompt"]},{"id":"context","g":"ai","word":"Context (çarçoveya naverokê)","text":"Her tiştê ku AI di dema xebatê de dibîne: rêwerz, peyamên te, pelên xwendî û bersivên berê.","noTip":1},{"id":"ctxwin","g":"ai","word":"Context window","text":"AI çiqas dikare di heman demê de di bîra xwe de bigire, bi token tê pîvandin. Gava ji wê derbas bibe, beşên kevn tên avêtin an kurt kirin.","also":["context windows","context window"]},{"id":"session","g":"ai","word":"Session (rûniştin)","text":"Yek sohbeta xebatê bi AI re, ji destpêk heta dawî. Sessioneke nû bi bîreke paqij dest pê dike.","also":["sessions","session","rûniştin"],"noTip":1},{"id":"memory","g":"ai","word":"Bîr (memory)","text":"Têbiniyên ku AI di navbera sessionan de digire, da ku tercîh û biryarên te yên berê bi bîr bîne.","noTip":1},{"id":"hallucination","g":"ai","word":"Hallucination (xeyalkirin)","text":"Gava AI tiştekî dibêje ku bi pêbawerî xuya dike lê ji ber xwe hatiye derxistin an şaş e. Agahiyên girîng kontrol bike.","also":["hallucinations","hallucinate","hallucinates","hallucination","xeyalkirin"]},{"id":"training","g":"ai","word":"Perwerdekirin (training)","text":"Fêrkirina modelekê bi nîşandana hejmareke mezin a mînakan, beriya ku kes wê bi kar bîne.","also":["trained","training","perwerdekirin"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Daneyên perwerdeyê","text":"Mînakên ku model jê fêr bû. Zanîna wê li roja berhevkirina wan daneyan radiweste.","also":["training set","training data","daneyên perwerdeyê"]},{"id":"cutoff","g":"ai","word":"Knowledge cutoff (sînorê zanînê)","text":"Roja ku zanîna AIyê ya hundirîn lê diqede. Heta ku lê negere, haya wê ji tiştên paşê tune.","also":["training cutoff","knowledge cutoff","sînorê zanînê"]},{"id":"finetune","g":"ai","word":"Fine-tuning","text":"Perwerdeya zêde ya modeleke heyî li ser mînakên te bi xwe, da ku di karekî taybet de baştir bibe.","also":["fine-tune","fine-tuned","fine tuning","fine-tuning"]},{"id":"inference","g":"ai","word":"Inference","text":"Dema ku modeleke AI bi rastî ji bo bersivdana tiştekî tê bikaranîn, berevajî perwerdekirinê.","also":["model inference","inference"]},{"id":"tooluse","g":"ai","word":"Tool use (bikaranîna amûran)","text":"Şiyana AI ku tiştan bike, ne tenê biaxive: fermanan bimeşîne, pelan bixwîne an li webê bigere, bi amûrên ku app dide wê.","also":["tool calling","tool call","tool calls","tool use","bikaranîna amûran"]},{"id":"subagent","g":"ai","word":"Subagent","text":"AIyeke alîkar ku AIya sereke karekî biçûktir dide wê û encamê ji wê distîne.","also":["subagents","sub-agent","subagent"]},{"id":"multiagent","g":"ai","word":"Multi-agent","text":"Çend AI bi hev re li ser yek perçe xebatê dixebitin, her yek bi beşa xwe, mîna tîmeke biçûk.","also":["multi-agent system","multi-agent"]},{"id":"autonomy","g":"ai","word":"Serxwebûn (autonomy)","text":"Berî ku divê ji kesekî bipirse, AI bi tena serê xwe çiqas dikare bike.","also":["autonomous","autonomy","serxwebûn"]},{"id":"hitl","g":"ai","word":"Human in the loop (mirov di çerxê de)","text":"Hiştina mirovekî di nav de da ku di xalên girîng de tiştê AI dike kontrol bike an erê bike. Di AI-gile de ew tu yî.","also":["human-in-the-loop","HITL","human in the loop"]},{"id":"guardrails","g":"ai","word":"Guardrails (sînorên parastinê)","text":"Sînor û kontrolên ku çalakiyên AI ewle dihêlin, mîna pêdiviya erêkirinê beriya ku tiştek zindî bibe. Xetera şaşiyan kêm dikin, lê wan bi temamî ji holê ranakin.","also":["guardrail","guardrails","sînorên parastinê"]},{"id":"rag","g":"ai","word":"Retrieval-augmented generation (RAG)","text":"Hiştina AI ku beriya bersivdanê tiştan di belgeyên te bi xwe de bibîne, da ku bersivên wê li ser rastiyên te bisekinin.","also":["RAG","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding","text":"Veguherandina nivîsê bo lîsteyeke hejmaran a ku wateya wê digire, da ku komputer tiştên bi wateyeke nêzîk bibîne.","also":["embeddings","embedding"]},{"id":"vectordb","g":"ai","word":"Vector database","text":"Databaseyek ku ji bo lêgerîna di wan lîsteyên hejmaran (embedding) de hatiye çêkirin, da ku materyalên bi wateyeke nêzîk bibîne.","also":["vector databases","vector store","vector database"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"Awayekî hevpar ji bo girêdana amûr û çavkaniyên daneyan bi appên AI ve, da ku AI bikaribe wan bi kar bîne.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperature (germahî)","text":"Mîhengek ku diyar dike bersivên AI çiqas maceraperest in. Nizm bersivên aramtir û pêşbînîkirîtir dide; bilind bersivên cihêtir. Tu yek jî wê her dem rast nake.","also":["model temperature","temperature","germahî"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"Dikare bi zêdetirî yek cureyê agahiyê bixebite, mîna nivîs, wêne û deng.","also":["multi-modal","multimodal"]},{"id":"evals","g":"ai","word":"Nirxandin (eval)","text":"Testeke plankirî ya ka AI li ser mînakên hilbijartî çiqas baş dike, da ku tu bikaribî model an promptan bidî ber hev.","also":["eval","evals","nirxandin"]},{"id":"bias","g":"ai","word":"Alîgirî (bias)","text":"Gava AI (an mirovek) bi nerast ber bi aliyekî ve diçe, pir caran ji ber tiştê jê fêr bûye.","also":["biased","bias","alîgirî"],"noTip":1},{"id":"responsible","g":"ai","word":"AI ya berpirsiyar","text":"Bikaranîna AI bi dadî, ewlehî û rastî, û mirov hê jî li hemberî encaman berpirsiyar in.","also":["ethical AI","responsible AI","AI ya exlaqî"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"Fenek ku tê de rêwerzên veşartî di rûpeleke webê an pelekê de hewl didin AIyê bixapînin da ku tiştekî bike ku bikarhênerê wê nexwestiye.","also":["prompt injections","prompt injection"]},{"id":"ratelimit","g":"ai","word":"Rate limit (sînorê rêjeyê)","text":"Sînorek li ser çend daxwazan tu dikarî di demeke diyarkirî de ji xizmetekê re bişînî. Heke tu jê derbas bibî, divê tu li bendê bimînî.","also":["rate limits","rate limited","rate limit","sînorê rêjeyê"]},{"id":"usagelimit","g":"ai","word":"Sînorê bikaranînê","text":"Plana te di heyamekê de çiqas xebata AI destûr dide; piştî wê, xebat radiweste an bihatir dibe.","also":["usage limits","usage limit","sînorên bikaranînê"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Çêkirina nermalavê bi piranî bi vegotina tiştê tu dixwazî ji AI re û hiştina ku ew kodê binivîse.","also":["vibe-coding","vibe coding"]},{"id":"budget","g":"money","word":"Budçe","text":"Mîqdara perê ku ji bo tiştekî tê veqetandin.","also":["budgets","budget","budçe"],"noTip":1},{"id":"costest","g":"money","word":"Texmîna lêçûnê","text":"Texmîna te ya herî baş li ser wê ku tiştek dê çiqas lê biçe, beriya ku tu dest pê bikî.","also":["cost estimates","cost estimate","texmînên lêçûnê"]},{"id":"roi","g":"money","word":"Return on investment (ROI) (qezenca veberhênanê)","text":"Tiştê ku tu paş ve distînî li hemberî tiştê te danî. Heke erênî be, hêjayî bû.","also":["ROI","qezenca veberhênanê"]},{"id":"tco","g":"money","word":"Total cost of ownership (TCO)","text":"Her tiştê ku tiştek bi rastî di tevahiya temenê xwe de lê diçe, ne tenê bihayê kirrînê: xebitandin, piştgirî, nûkirin û di dawiyê de teqawîdkirin.","also":["TCO"]},{"id":"capex","g":"money","word":"CapEx û OpEx","text":"CapEx ew pere ye ku pêşwext li ser tiştên ku tu dihêlî tê xerckirin; OpEx xerciya berdewam e, mîna fatûreyên mehane.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Abonetî (subscription)","text":"Dayîna pereyan bi rêkûpêk, bi gelemperî mehane an salane, da ku tu bikaribî berdewam tiştekî bi kar bînî.","also":["subscriptions","subscription","abonetî"],"noTip":1},{"id":"saas","g":"money","word":"Software as a service (SaaS)","text":"Nermalava ku tu bi serhêl bi kar tînî û bi abonetiyê pere didî, dema ku çêker ji bo te wê dimeşîne.","also":["SaaS"]},{"id":"payg","g":"money","word":"Pay as you go","text":"Dayîna pere tenê ji bo tiştê tu bi kar tînî, mîna cloud computing an tokenên AI.","also":["pay-as-you-go","usage-based pricing","pay as you go"]},{"id":"overage","g":"money","word":"Overage (bikaranîna zêde)","text":"Bikaranîna ji ya ku plana te dihewîne zêdetir, ku dibe ku zêdetir lê biçe.","also":["overages","overage charges","overage","bikaranîna zêde"]},{"id":"billingalert","g":"money","word":"Billing alert","text":"Peyamek gava xerc an bikaranîn digihîje asteke ku te hilbijartiye. Te hişyar dike, lê her dem pêşî li lêçûnên din nagire.","also":["billing alerts","spending alert","billing alert"]},{"id":"freetier","g":"money","word":"Free tier (asta belaş)","text":"Asteke belaş a xizmeteke bi pere, bi sînoran. Ji bo destpêkirinê bikêr e.","also":["free plan","free tier","asta belaş"]},{"id":"pricing","g":"money","word":"Plana bihayê","text":"Pakêtên cuda yên ku xizmetek difiroşe, her yek bi biha û sînorên xwe.","also":["pricing plans","price plan","pricing plan","planên bihayê"]},{"id":"licence","g":"money","word":"Lîsans","text":"Rêzikên ku diyar dikin tu dikarî tiştê kesekî din çêkiriye, mîna nermalav, nivîsk an wêne, çawa bi kar bînî, kopî bikî, biguherînî an parve bikî.","also":["licences","license","licenses","lîsans"],"noTip":1},{"id":"opensource","g":"money","word":"Open source (çavkaniya vekirî)","text":"Nermalava ku her kes dikare koda wê bixwîne, bi kar bîne û pir caran bi belaşî biguherîne, di bin rêzikên lîsansa wê de.","also":["open-source","open source software","OSS","open source","çavkaniya vekirî"]},{"id":"osslicence","g":"money","word":"Lîsansa open source","text":"Rêzikên ku bi koda open source re têne. Hinek hema hema her tiştî destûr didin (mîna MIT); hinek dixwazin guhertinên te jî parve bikî (mîna GPL).","also":["open source licences","MIT licence","GPL","open source licence","lîsansên open source"]},{"id":"proprietary","g":"money","word":"Proprietary (taybet)","text":"Ya şirketekê ye û ne azad e ku were kopîkirin an guhertin. Berevajiyê open source e.","also":["proprietary software","proprietary","taybet"]},{"id":"copyright","g":"money","word":"Mafê çapê (copyright)","text":"Mafê qanûnî yê çêkerekî ji bo kontrolkirina kopiyên xebata xwe, kod û nivîs jî tê de.","also":["copyrighted","copyright","mafê çapê"],"noTip":1},{"id":"ip","g":"money","word":"Milkiyeta fikrî (IP)","text":"Raman û afirandinên ku qanûn wekî yên xwediyekî dihesibîne, mîna kod, sêwiran, nav û logo.","also":["intellectual property","milkiyeta fikrî"]},{"id":"tos","g":"money","word":"Mercên xizmetê","text":"Rêzikên ku tu gava xizmetekê bi kar tînî dipejirînî.","also":["terms and conditions","terms of use","terms of service","mercên xizmetê","mercên bikaranînê"]},{"id":"contract","g":"money","word":"Peyman","text":"Lihevkirineke nivîskî di navbera du aliyan de ku qanûn piştgiriyê dide wê.","also":["contracts","contract","peyman","peymanname"],"noTip":1},{"id":"sow","g":"money","word":"Statement of work (SOW)","text":"Belgeyek ku tam diyar dike kîjan xebat dê were kirin, heta kengê û bi çiqas.","also":["SOW"]},{"id":"fixedprice","g":"money","word":"Bihayê sabît","text":"Bihayekî lihevkirî ji bo tevahiya kar, çiqas dem bigire jî.","also":["fixed-price","fixed price","bihayê sabît"]},{"id":"tm","g":"money","word":"Dem û materyal (T&M)","text":"Dayîna pereyan ji bo saetên ku bi rastî hatine xebitandin û tiştên ku bi rastî hatine bikaranîn, li şûna bihayekî diyarkirî.","also":["T&M","time and materials","dem û materyal"]},{"id":"invoice","g":"money","word":"Fatûre","text":"Belgeyek ku ji bo xebata kirî an tiştên peydakirî daxwaza pereyan dike.","also":["invoices","invoice","fatûre"],"noTip":1},{"id":"lockin","g":"money","word":"Vendor lock-in","text":"Gava ku dûrketina ji peydakerekî ewqas zehmet an biha ye ku tu bi wî ve girêdayî dimînî.","also":["lock-in","vendor lock-in"]},{"id":"procurement","g":"money","word":"Procurement (kirrîn)","text":"Pêvajoya hilbijartin û kirrîna ji peydakeran.","also":["procurement","kirrîn"]},{"id":"servicecredit","g":"money","word":"Service credit","text":"Vegerandina pereyan an daxistinek ku tu distînî gava peydakerek SLAya xwe bi cih nayîne.","also":["service credits","service credit"]}]}};
